L["preview the prompt with a mock candidate"] = "가상의 대상으로 알림창 미리보기"
L["the favour ledger: who buffed you, what you gave back, and who you buffed"] = "호의 장부: 나에게 버프를 준 사람, 내가 보답한 것, 내가 버프를 준 사람"
L["what this addon does, and the one thing it needs from you"] = "이 애드온이 하는 일과 직접 해야 할 한 가지"
L["make a /click macro for your action bar"] = "행동 단축바용 /click 매크로 만들기"
L["unlock the prompt so it can be dragged"] = "끌어서 옮길 수 있게 알림창 잠금 해제"
L["lock it again -- an unlocked prompt never casts"] = "다시 잠금 -- 잠금 해제된 알림창은 시전하지 않음"
L["list who is never offered anything, or put somebody on that list"] = "제외 목록 보기, 또는 누군가를 목록에 추가"
L["take somebody off the never-offer list"] = "제외 목록에서 빼기"
L["switch handing your target back after buffing on or off"] = "버프 후 원래 대상 되돌리기 켜기/끄기"
L["switch the chat lines about who buffed you on or off"] = "누가 나에게 버프를 줬는지 알리는 대화창 메시지 켜기/끄기"
L["copy these settings as one line of text"] = "현재 설정을 한 줄 문자열로 복사"
L["use settings somebody exported, or undo the last import"] = "다른 사람이 내보낸 설정 적용, 또는 마지막 가져오기 취소"
L["what your class and this build allow"] = "내 직업과 이 빌드에서 가능한 것"
L["the last few things that broke"] = "최근 발생한 오류 몇 건"
L["tools for testing the addon on this client: the click log, try, look and forms"] = "이 클라이언트에서 애드온을 시험하는 도구: 클릭 기록, try, look, forms"
L["log what the button does when clicked"] = "클릭 시 버튼 동작 기록"
L["run any macro text from the prompt"] = "알림창에서 원하는 매크로 내용 실행"
L["dump every API answer for a unit"] = "유닛에 대한 모든 API 응답 출력"
L["example macros to try"] = "시험해 볼 매크로 예시"
L["Manners commands:"] = "Manners 명령어:"
L["|cffffd100/mnr|r works in place of |cffffd100/manners|r in all of them."] = "모든 명령에서 |cffffd100/manners|r 대신 |cffffd100/mnr|r 형태로 써도 됩니다."
L["try cleared -- the normal cast takes effect when this fight ends; until then a press runs the macro already on the button."] = "try 해제됨 -- 일반 시전은 이 전투가 끝나면 적용됩니다. 그때까지는 누르면 버튼에 이미 있는 매크로가 실행됩니다."
L["try cleared -- back to the normal cast."] = "try 해제됨 -- 일반 시전으로 돌아갑니다."
L["try armed: |cff80ff80%s|r"] = "try 장전됨: |cff80ff80%s|r"
L["|cffff8080not armed for now:|r %s."] = "|cffff8080지금은 장전 안 됨:|r %s."
L["expands to: |cffffffff%s|r"] = "변환 결과: |cffffffff%s|r"
L["%d characters -- %d over the %d a macro body holds. The client will cut it, and what runs is not what is printed above."] = "%d바이트 -- 매크로 본문 한도를 %d바이트 넘습니다(한도 %d바이트). 클라이언트가 잘라 내므로, 실제로 실행되는 내용은 위에 출력된 것과 다릅니다."
L["It takes effect when this fight ends; until then a press runs the macro already on the button. |cffffd100/manners try|r with nothing clears it."] = "이 전투가 끝나면 적용됩니다. 그때까지는 누르면 버튼에 이미 있는 매크로가 실행됩니다. 내용 없이 |cffffd100/manners try|r 입력 시 해제됩니다."
L["The prompt arms it once they have one. |cffffd100/manners try|r with nothing clears it."] = "알림창 대상에게 유닛 토큰이 생기면 장전됩니다. 내용 없이 |cffffd100/manners try|r 입력 시 해제됩니다."
L["Click the prompt to run it. |cffffd100/manners try|r with nothing clears it."] = "알림창을 클릭하면 실행됩니다. 내용 없이 |cffffd100/manners try|r 입력 시 해제됩니다."
L["Targeting forms, for /manners try:"] = "/manners try용 대상 지정 형식:"
L["(on yourself)"] = "(나에게 시전)"
L["Tokens: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} is what a debt is filed under, {aim} is what a targeting line wants. Use \\n for a new line."] = "토큰: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name}: 보답할 호의가 기록되는 이름, {aim}: 대상 지정 줄에 들어가는 값. 줄을 바꾸려면 \\n 입력."
L["the favour ledger did not load -- reinstalling Manners should bring it back."] = "호의 장부를 불러오지 못했습니다 -- Manners를 다시 설치하면 돌아올 것입니다."
L["unlocked -- it can be dragged once this fight ends; until then a press still casts what the fight froze. Then |cffffd100/manners lock|r."] = "잠금 해제됨 -- 이 전투가 끝나면 끌어서 옮길 수 있습니다. 그때까지는 누르면 전투 중 고정된 주문이 시전됩니다. 그다음 |cffffd100/manners lock|r 입력."
L["unlocked -- it can be dragged once this fight ends; nothing is armed meanwhile. Then |cffffd100/manners lock|r."] = "잠금 해제됨 -- 이 전투가 끝나면 끌어서 옮길 수 있습니다. 그때까지는 장전된 것이 없습니다. 그다음 |cffffd100/manners lock|r 입력."
L["unlocked -- drag the prompt, then |cffffd100/manners lock|r."] = "잠금 해제됨 -- 알림창을 끌어서 옮긴 뒤 |cffffd100/manners lock|r 입력."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- |cffffd100/manners on|r first."] = "잠금을 풀었지만 애드온이 |cffff8080꺼짐|r 상태라 끌어서 옮길 알림창이 없습니다 -- 먼저 |cffffd100/manners on|r 입력."
L["locked."] = "잠갔습니다."
L["hand your target back after buffing: |cff00ff00on|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "버프 후 원래 대상 되돌리기: |cff00ff00켜짐|r -- 이 전투가 끝나면 적용됩니다. 그때까지는 누르면 버튼에 이미 있는 매크로가 실행됩니다."
L["hand your target back after buffing: |cffff0000off|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "버프 후 원래 대상 되돌리기: |cffff0000꺼짐|r -- 이 전투가 끝나면 적용됩니다. 그때까지는 누르면 버튼에 이미 있는 매크로가 실행됩니다."
L["hand your target back after buffing: |cff00ff00on|r"] = "버프 후 원래 대상 되돌리기: |cff00ff00켜짐|r"
L["hand your target back after buffing: |cffff0000off|r"] = "버프 후 원래 대상 되돌리기: |cffff0000꺼짐|r"
L["click logging: |cff00ff00on|r"] = "클릭 기록: |cff00ff00켜짐|r"
L["click logging: |cffff0000off|r"] = "클릭 기록: |cffff0000꺼짐|r"
L["verbose: |cff00ff00on|r -- a line in your own chat when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed"] = "대화창 알림: |cff00ff00켜짐|r -- 누군가 나에게 버프를 줄 때, 호의를 보답한 것으로 처리할 때, 클릭이 실패하거나 건너뛰었거나 보답하지 못한 채 끝났을 때 내 대화창에 한 줄씩 표시"
L["verbose: |cffff0000off|r"] = "대화창 알림: |cffff0000꺼짐|r"
L["enabled."] = "켜졌습니다."
L["disabled."] = "꺼졌습니다."
L["nobody is on your never-offer list. Shift-right-click the prompt to put whoever it is showing on it."] = "제외 목록이 비어 있습니다. 알림창을 Shift+오른쪽 클릭하면 지금 떠 있는 사람을 목록에 넣습니다."
L["never offered anything unless they buff you: %s"] = "나에게 버프를 주지 않는 한 띄우지 않음: %s"
L["say who: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lists everybody on the list."] = "누구인지 입력하세요: |cffffd100/manners allow Name|r. |cffffd100/manners never|r 명령으로 목록 전체를 볼 수 있습니다."
L["|cffffffff%s|r can be offered again."] = "|cffffffff%s|r님이 다시 알림창에 뜰 수 있습니다."
L["nobody called %s is on your never-offer list."] = "%s님은 제외 목록에 없습니다."
L["snooze takes a number of minutes from 1 to %d, or off -- for example |cffffd100/manners snooze 15|r or |cffffd100/manners snooze 1h|r."] = "snooze 뒤에는 1에서 %d 사이의 분 단위 숫자나 off를 입력하세요 -- 예: |cffffd100/manners snooze 15|r 또는 |cffffd100/manners snooze 1h|r."
L["type |cffffd100/manners import|r followed by a settings string."] = "|cffffd100/manners import|r 뒤에 설정 문자열을 이어서 입력하세요."
L["Tools for testing Manners on this client:"] = "이 클라이언트에서 Manners를 시험하는 도구:"
L["nothing has broken this session."] = "이번 접속 중 발생한 오류가 없습니다."
L["|cffffd100the last %d of %d|r |cff808080(%d kept)|r:"] = "|cffffd100최근 %d건 (전체 %d건)|r |cff808080(%d건 보관 중)|r:"
L["|cffffd100the last %d of %d|r:"] = "|cffffd100최근 %d건 (전체 %d건)|r:"
L["Flavour.lua did not load -- check the toc's file list"] = "Flavour.lua를 불러오지 못했습니다 -- toc 파일 목록을 확인하세요"
L["|cffff4040this client has never heard of %s|r -- Manners has the wrong spell ids for %s on %s. Please report this line."] = "|cffff4040이 클라이언트는 주문 %s을(를) 모릅니다|r -- Manners에 있는 %s 버프의 주문 ID가 %s 기준으로 틀렸습니다. 이 줄을 제보해 주세요."
L["owes returning: |cffffffff%s|r (%ds left, buffed you %ds ago)"] = "보답할 호의: |cffffffff%s|r (%d초 남음, %d초 전에 나에게 버프를 줌)"
L["not watching for favours -- Manners is switched off."] = "호의를 감시하지 않음 -- Manners가 꺼져 있습니다."
L["nobody has buffed you recently."] = "최근 나에게 버프를 준 사람이 없습니다."
L["|cffff8080own buffs: last scan not believed (%s)|r -- %d read, baseline %d"] = "|cffff8080내 버프: 마지막 스캔을 신뢰하지 않음 (%s)|r -- %d개 읽음, 기준 %d개"
L["|cffffd100own buffs: baseline not settled|r -- %d read, waiting for a second scan to agree"] = "|cffffd100내 버프: 기준 미확정|r -- %d개 읽음, 두 번째 스캔 결과가 일치하기를 기다리는 중"
L["own buffs: %d read, baseline %d"] = "내 버프: %d개 읽음, 기준 %d개"
L["thank with an emote: |cff00ff00on|r"] = "감정 표현으로 감사 인사: |cff00ff00켜짐|r"
L["thank with an emote: |cffff0000off|r"] = "감정 표현으로 감사 인사: |cffff0000꺼짐|r"
L["last thanked: |cffffffff%s|r, %ds ago (the game answered %s)"] = "마지막 감사 인사: |cffffffff%s|r, %d초 전 (게임 응답: %s)"
L["last not thanked: |cffffffff%s|r, %ds ago (%s)"] = "마지막으로 생략한 감사 인사: |cffffffff%s|r, %d초 전 (%s)"
L["switched OFF on this profile -- nothing is recorded or offered; /manners on"] = "이 프로필에서 꺼짐 -- 아무것도 기록하거나 띄우지 않음; /manners on"
L["prompt is UNLOCKED -- it will not buff anyone until you /manners lock"] = "알림창 잠금 해제됨 -- /manners lock 입력 전까지 아무에게도 버프를 주지 않음"
L["|cffffd100snoozed until %s|r -- no prompt until then; /manners snooze off ends it"] = "|cffffd100%s까지 숨김|r -- 그때까지 알림창이 뜨지 않음; /manners snooze off 입력 시 종료"
L["|cffffd100mounted|r -- Not while mounted keeps the prompt away until you get off"] = "|cffffd100탈것 탑승 중|r -- 탈것 탑승 중 숨기기 옵션 때문에 내릴 때까지 알림창이 뜨지 않음"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only people who buffed you or asked are offered"] = "|cffffd100마나 절약 중|r -- 마나가 %d%%로 회복될 때까지 나에게 버프를 주거나 요청한 사람만 뜸"
L["|cffffd100ready check|r -- your party or raid comes first until the pull"] = "|cffffd100전투 준비|r -- 전투가 시작될 때까지 내 파티나 공격대가 먼저 뜸"
L["|cffffd100raid groups|r -- in a raid, only groups %s are offered unasked"] = "|cffffd100공격대 파티|r -- 공격대에서는 %s파티만 요청 없이 뜸"
L["|cffffd100raid groups|r -- every group is unticked, so in a raid nobody is offered unasked"] = "|cffffd100공격대 파티|r -- 모든 파티가 선택 해제되어 있어, 공격대에서는 아무도 요청 없이 뜨지 않음"
L["|cffff8080/manners try is armed:|r %s -- clear it with a bare /manners try"] = "|cffff8080/manners try 장전됨:|r %s -- 내용 없이 /manners try 입력 시 해제"
L["queue now: %d"] = "현재 대기열: %d"
L["queue if switched on: %d"] = "켰을 때 대기열: %d"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "|cffffd100/manners %s|r 명령은 없습니다 -- 혹시 |cffffd100/manners %s|r 명령을 찾으셨나요? |cffffd100/manners help|r 명령으로 전체 목록을 볼 수 있습니다."
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "|cffffd100/manners %s|r 명령은 없습니다 -- 혹시 |cffffd100/manners %s|r 명령을 찾으셨나요? |cffffd100/manners dev|r 명령으로 시험 도구 목록을 볼 수 있습니다."
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "고맙구먼, {name}! 대장간에 돌아가면 첫 잔은 내가 사지."
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "신세 졌네, {name}. 이제 자넨 산의 친구일세."
L["Thank ye, {name}! I'd have been fine without it, mind. But thank ye."] = "고맙구먼, {name}! 없어도 끄떡없었겠지만. 그래도 고맙네."
L["Bless ye, {name}! I'd hug ye, but ye'd be needin' a healer after."] = "고맙네, {name}! 한번 안아 주고 싶다만, 그럼 자네가 치유사 신세일세."
L["Paid back already, {name}. Quicker than I've ever settled a bar tab."] = "벌써 갚았네, {name}. 내 평생 술값도 이리 빨리 갚아 본 적이 없구먼."
L["I'll tell this at the Thunderbrew like ye saved me life, {name}. Thank ye!"] = "썬더브루에선 자네가 내 목숨을 구했다고 떠벌릴 걸세, {name}. 고맙네!"
L["Grand, {name}! I'd carve ye a statue, but this is quicker."] = "훌륭하네, {name}! 석상이라도 깎아 주고 싶지만, 이게 더 빠르지."
L["The Titans made us of stone, {name}, but that still touched me. Thank ye."] = "티탄께서 돌로 빚은 이 가슴도 찡하구먼, {name}. 고맙네."
L["Aye, {name}, ye only had to ask. Hold still now, like a good anvil."] = "암, {name}, 말만 하면 되지. 모루처럼 가만있어 보게."
L["Say no more, {name}. Stone and steel, here it comes."] = "두말하면 잔소리지, {name}. 돌과 강철의 힘, 받게!"
L["Ask a dwarf fer help, {name}, and ye'll get it. Loudly."] = "드워프한테 도움을 청하면 받긴 받네, {name}. 시끄럽게."
L["Right, {name}. Brace yerself; I do everything like I'm swingin' a hammer."] = "좋아, {name}. 단단히 버티게. 난 뭘 하든 망치 휘두르듯 하니까."
L["Aye, {name}, and a story about it ye didn't ask fer. Where to begin..."] = "암, {name}. 덤으로 묻지도 않은 얘기까지 해 주지. 어디 보자..."
L["One {buff}, pulled fresh like a proper pint, {name}."] = "{name}, 갓 뽑은 생맥주처럼 시원한 {buff} 한 잔일세."
L["Done, {name}. Dwarven work: over-built, under-priced and guaranteed."] = "다 됐네, {name}. 드워프 솜씨라 쓸데없이 튼튼하고, 값싸고, 평생 보증일세."
L["Here, {name}, a wee somethin' to keep ye on yer feet. Wee, like me."] = "옜네, {name}. 버티라고 주는 쪼끄만 선물일세. 나처럼 쪼끄맣지."
L["Off ye go, {name}, steady as the mountain."] = "가 보게, {name}. 산처럼 든든하게!"
L["Here, {name}. Ale's for after; this is for before."] = "옜네, {name}. 맥주는 싸운 뒤에, 이건 싸우기 전에."
L["Magni turned to diamond fer the cause, {name}. This is the cheaper option."] = "마그니 님은 대의를 위해 다이아몬드가 되셨지, {name}. 이건 보급형일세."
L["A dwarf's got yer back, {name}. Well, yer knees. Close enough."] = "자네 등 뒤는 드워프가 지키네, {name}. 뭐, 무릎 뒤지만. 비슷하지."
L["If a trogg bothers ye, {name}, tell it a dwarf sent ye. Then run."] = "트로그가 귀찮게 굴면, {name}, 드워프가 보냈다고 하게. 그리고 튀게."
L["If it wears off, {name}, give it a good thump. That's how we fix everything."] = "효과가 떨어지면, {name}, 한 대 쾅 치게. 우린 뭐든 그렇게 고치지."
L["Take this, {name}. I'd give ye some stubbornness too, but I'm usin' all mine."] = "받게, {name}. 고집도 좀 나눠 주고 싶다만, 내 건 내가 다 쓰는 중일세."
L["Stone and hammer keep ye, cousin {name}!"] = "돌과 망치가 자넬 지켜 주길, 사촌 {name}!"
L["Three Hammers, one round, cousin {name}!"] = "망치는 셋, 술잔은 하나일세, 사촌 {name}!"
L["Yer cousin's cousin married mine, {name}, I'd wager. It's a small mountain."] = "자네 사촌의 사촌이 내 사촌과 혼인했을걸, {name}. 산이 좁잖나."
L["Two dwarves together, {name}. Pity whatever's standin' in our way."] = "드워프가 둘이나 뭉쳤네, {name}. 앞길 막는 놈들만 불쌍하게 됐구먼."
L["Stand behind me, {name}. Aye, I know. Crouch a bit."] = "내 뒤에 서게, {name}. 암, 아네. 좀 쭈그리게."
L["Right, {name}: I take the front, ye take the loot, and we argue after."] = "자, {name}. 앞은 내가, 전리품은 자네가. 다툼은 그다음일세."
L["If I start singin', {name}, the fight's gone well. Or very badly."] = "내가 노래를 부르면, {name}, 싸움이 잘 풀린 걸세. 아니면 아주 망했거나."
L["Dwarves never leave a mate behind, {name}. Nor a keg. Mates first, mind."] = "드워프는 동료를 두고 가지 않네, {name}. 술통도. 물론 동료가 먼저지."
L["Beards out, {name}! Them without beards, look fierce. It's nearly as good."] = "수염 내밀게, {name}! 수염 없는 친구는 인상이라도 쓰게. 거의 비슷하네."
L["Mornin', {name}! Too early for ale. Almost. Have this first."] = "좋은 아침일세, {name}! 맥주엔 아직 이르지. 거의. 이거부터 받게."
L["Up with the forge fires, {name}! A dwarf's day starts with a hammer and this."] = "화로와 함께 기상일세, {name}! 드워프의 하루는 망치와 이걸로 시작하지."
L["Early, {name}? Nonsense. The mine's been open two hours. Here."] = "이르다고, {name}? 무슨 소리. 광산은 두 시간 전에 열었네. 옜네."
L["My thanks, {name}. Let me return the kindness before a bard gets it wrong."] = "고맙소, {name}. 음유시인이 멋대로 지어내기 전에 내가 먼저 갚으리다."
L["Kindly done, {name}. Let no one say we forget a friend."] = "친절에 감사하오, {name}. 우린 친구를 잊지 않는다오."
L["Thank you, {name}. I'd knight you, but apparently I 'need permission'."] = "고맙소, {name}. 기사 작위라도 주고 싶지만, '허가가 필요하다'는구려."
L["Repaid on the spot, {name}. In Stormwind that'd take three forms and a stamp."] = "즉석에서 갚았소, {name}. 스톰윈드였다면 서류 세 장에 도장까지 필요했을 거요."
L["Thanks, {name}. I'd pay in gold, but Stormwind still owes the stonemasons."] = "고맙소, {name}. 금화로 갚고 싶지만, 스톰윈드가 아직 석공 조합에 빚이 있어서."
L["Much obliged, {name}. Mother said always return a kindness. And the dish."] = "신세 졌소, {name}. 어머니께서 그릇은 빈 채로 돌려주는 게 아니라 하셨소."
L["Thank you, {name}. Consider the scales balanced, by royal decree. Mine."] = "고맙소, {name}. 왕명으로 이 빚은 청산하오. 내가 내린 왕명이오."
L["You shame me, {name}; I should have thought of it first. Allow me."] = "부끄럽구려, {name}. 내가 먼저 했어야 하는데. 이제라도 갚으리다."
L["Of course, {name}. Hold still and look heroic; it helps the bards."] = "물론이오, {name}. 가만히, 영웅다운 표정으로. 음유시인들이 좋아하오."
L["Right away, {name}. Keep your shield high."] = "당장 하리다, {name}. 방패를 높이 드시오."
L["More work? Gladly, {name}. It beats the lumber mill."] = "일감이오? 기꺼이, {name}. 제재소보단 낫소."
L["Of course, {name}. Humans excel at helping and overpromising. This is helping."] = "물론이오, {name}. 인간은 돕기와 큰소리치기에 능하오. 이건 돕는 쪽이오."
L["Certainly, {name}. Humans are quick learners; I learned this one yesterday."] = "그러리다, {name}. 인간은 배우는 게 빠르오. 이것도 어제 배웠소."
L["Hold still, {name}, like a statue in the Valley of Heroes. You'd fit right in."] = "가만히 계시오, {name}. 영웅의 골짜기 석상처럼. 딱 어울리겠소."
L["Right away, {name}. The Light helps those who ask. So do I, and I'm quicker."] = "당장 하리다, {name}. 빛은 구하는 자를 돕소. 나도 돕소. 더 빨리."
L["The road ahead is long, {name}. This won't shorten it, but it'll help."] = "갈 길이 멀다오, {name}. 길을 줄여 주진 못해도 도움은 될 거요."
L["Fair winds and following seas, {name}."] = "순풍과 잔잔한 바다가 함께하길, {name}."
L["Take this, {name}. Elves have centuries to be generous; I've got fifty years."] = "받으시오, {name}. 엘프는 수백 년간 베풀면 되지만, 난 한 오십 년뿐이오."
L["A little something, {name}. Don't tell the guards; they'll all want one."] = "작은 선물이오, {name}. 경비병들한텐 비밀이오. 다들 달라고 할 테니."
L["Here, {name}. If a kobold asks, you don't have a candle."] = "받으시오, {name}. 코볼트가 물으면, 양초는 없다고 하시오."
L["For you, {name}. A human gift: well meant, hastily made, surprisingly sturdy."] = "받으시오, {name}. 인간식 선물이오. 뜻은 좋고, 급히 만들었고, 의외로 튼튼하오."
L["Mind the murlocs, {name}. Take this; I've seen what they do to a picnic."] = "멀록 조심하시오, {name}. 받으시오. 놈들이 소풍을 어떻게 망치는지 봤소."
L["Every road needs a hero, {name}. Today it's me, apparently. Take this."] = "모든 길엔 영웅이 필요하오, {name}. 오늘은 나인가 보오. 받으시오."
L["Arathor's children stand together, {name}."] = "아라소르의 후예는 함께 서는 법이오, {name}."
L["A fellow human, {name}! Quick, let's found a kingdom before lunch."] = "같은 인간이구려, {name}! 어서 점심 전에 왕국이나 하나 세웁시다."
L["Stormwind or Boralus, {name}, we'll both complain about the weather."] = "스톰윈드든 보랄러스든, {name}, 날씨 불평하는 건 매한가지요."
L["Human to human, {name}: no, I don't know why everything happens to us either."] = "인간끼리 하는 말인데, {name}. 왜 만날 우리한테만 일이 터지는지 나도 모르겠소."
L["Keep close, {name}. Humans have always won by outnumbering things."] = "가까이 붙으시오, {name}. 인간은 늘 머릿수로 이겨 왔소."
L["Stay in formation, {name}. We haven't got one, but stay in it anyway."] = "대형을 유지하시오, {name}. 대형은 없지만, 아무튼 유지하시오."
L["I'll draw up a plan, {name}, and then we can all ignore it together."] = "작전을 짜 오리다, {name}. 그리고 다 같이 무시합시다."
L["Every hero in the songs had friends, {name}. Nobody sings about them. I will."] = "노래 속 영웅 곁엔 늘 동료가 있었소, {name}. 그들의 노래는 내가 부르리다."
L["Shields up, {name}. Stormwind taught me to march; nobody taught me to stop."] = "방패를 드시오, {name}. 스톰윈드는 행군은 가르쳐도 멈추는 법은 안 가르쳤소."
L["Ishnu-alah, {name}. Returned the same day, which for a kaldorei is rushing."] = "Ishnu-alah, {name}. 당일에 갚다니, 칼도레이로선 서두른 셈이오."
L["Thank you, {name}. Elune smiles on the generous."] = "감사하오, {name}. 엘룬께선 베푸는 이에게 미소 지으신다오."
L["Thank you, {name}. Even the wisps glow brighter, and they're hard to impress."] = "감사하오, {name}. 좀처럼 감동 않는 위습들마저 더 밝게 빛나는구려."
L["Elune saw that, {name}. She sees everything, so I had best return it."] = "엘룬께서 보셨소, {name}. 다 보시는 분이니, 얼른 갚아야겠소."
L["Thank you, {name}. Returned before I nap for a century or two."] = "감사하오, {name}. 한 이백 년 낮잠 들기 전에 갚아 두리다."
L["Thank you, {name}. The Ancients will hear of this. They're dreadful gossips."] = "감사하오, {name}. 고대정령들 귀에도 들어갈 거요. 소문을 워낙 좋아해서."
L["Thank you, {name}. I'll tell the Sentinels to stop aiming at you."] = "감사하오, {name}. 파수대에 그대를 그만 겨누라 일러 두리다."
L["My people never hurry, {name}. For you, an exception."] = "우리 종족은 서두르는 법이 없소, {name}. 그대만은 예외요."
L["Gladly, {name}. Be still, and let the moonlight find you."] = "기꺼이, {name}. 가만히, 달빛이 그대에게 닿도록."
L["Of course, {name}. Elune's blessings are meant to be shared."] = "물론이지요, {name}. 엘룬의 축복은 나누라고 있는 것이니."
L["At last, {name}! I've waited ten thousand years for someone to ask."] = "드디어, {name}! 누가 청해 주길 만 년이나 기다렸소."
L["No riddle, no omen from Elune, {name}. Just a plain yes, for once."] = "수수께끼도, 엘룬의 계시도 없소, {name}. 이번만은 그저 '그러겠소'."
L["Of course, {name}. Ask in Darnassian next time and I'll add a bow."] = "물론이오, {name}. 다음엔 다르나서스어로 청하면 절까지 해 드리리다."
L["Elune already said yes, {name}. I'm merely catching up."] = "엘룬께선 이미 허락하셨소, {name}. 난 뒤따를 뿐이오."
L["Of course, {name}. Stand still and pretend you're a tree. It helps."] = "물론이오, {name}. 가만히, 나무인 척하시오. 도움이 되오."
L["Elune-adore, {name}. Walk softly; the trees are light sleepers."] = "Elune-adore, {name}. 사뿐히 걸으시오. 나무들은 잠귀가 밝으니."
L["May the forest shelter you, {name}, wherever you roam."] = "{name}, 어디를 가든 숲이 그대를 품어 주기를."
L["A gift from the shadows, {name}. No, don't look. You won't find me."] = "그림자 속에서 주는 선물이오, {name}. 아니, 찾지 마시오. 못 찾을 테니."
L["Elune lights your path, {name}. I'm merely holding the lantern."] = "엘룬께서 그대의 길을 비추시오, {name}. 난 등불만 들었을 뿐."
L["The owls pointed you out, {name}. They have strong opinions. Here."] = "부엉이들이 그대를 콕 집었소, {name}. 안목 까다로운 녀석들이오. 받으시오."
L["Tyrande would insist, {name}, and nobody argues with Tyrande."] = "티란데 님이라면 꼭 주라 하셨을 거요, {name}. 그분께 토 다는 자는 없지."
L["Take this, {name}. The last one went to a hippogryph. It was less grateful."] = "받으시오, {name}. 지난번엔 히포그리프에게 줬는데, 그놈은 고마운 줄 모르더군."
L["Mind the wildlife, {name}. Half of it is a druid, and all of it is watching."] = "짐승들을 조심하시오, {name}. 절반은 드루이드고, 전부 지켜보고 있소."
L["Ishnu-alah, {name}. Elune keeps her children close."] = "Ishnu-alah, {name}. 엘룬께선 자녀들을 늘 곁에 두시지요."
L["Of course I saw you, {name}. It takes a kaldorei to spot a kaldorei."] = "당연히 보였소, {name}. 칼도레이는 칼도레이가 알아보는 법."
L["One kaldorei to another, {name}: we lost a tree, never each other."] = "칼도레이끼리 하는 말이오, {name}. 나무는 잃어도 서로는 잃지 않았소."
L["A kaldorei never leaves kin in the dark, {name}. Unless it's for cover."] = "칼도레이는 동족을 어둠 속에 두지 않소, {name}. 숨으려는 게 아니라면."
L["Quick one, {name}? By kaldorei reckoning we'll be done before we start."] = "금방 끝내자고, {name}? 칼도레이 셈법으론 시작 전에 끝난 셈이오."
L["I'll be the one you can't see, {name}. That's not a mistake; that's the plan."] = "난 안 보이는 쪽을 맡으리다, {name}. 실수가 아니라 작전이오."
L["Elune watches the whole party, {name}. I'm just the one who waves at her."] = "엘룬께서 파티 전체를 지켜보시오, {name}. 난 손 흔드는 담당이고."
L["Ten thousand years of companions, {name}. You lot rank rather high."] = "만 년 동안 동료를 겪어 봤소, {name}. 그대들은 꽤 상위권이오."
L["Stay close, {name}. We kaldorei misplaced two World Trees. Not you, though."] = "곁에 있으시오, {name}. 우린 세계수를 둘이나 잃었소. 그대는 안 잃으리다."
L["The moon's up, {name}. For a kaldorei, this is the middle of the morning."] = "달이 떴소, {name}. 칼도레이에겐 지금이 한창 아침이오."
L["Everyone sensible is asleep, {name}. Elune and I prefer it this way."] = "멀쩡한 이들은 다 잠들었소, {name}. 엘룬과 나는 이 편이 좋소."
L["Moonlight suits you, {name}. This is merely a second layer."] = "달빛이 잘 어울리는구려, {name}. 이건 한 겹 더 입혀 드리는 것뿐."
L["Morning, {name}. My people slept through these for millennia. I'm adapting."] = "아침이구려, {name}. 우린 수천 년간 아침엔 잤소. 적응 중이오."
L["Dawn, {name}. Elune's gone to bed, so I'm covering for her."] = "새벽이오, {name}. 엘룬께서 주무시러 가셨으니 내가 대신하리다."
L["The sun's up, {name}, and so, reluctantly, am I."] = "해가 떴소, {name}. 나도 마지못해 일어났소."
L["The shadows remember kindness, {name}. So do I."] = "그림자는 친절을 기억하지요, {name}. 저도 마찬가지고요."
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "고마워요, {name}. 렌도레이는 받은 호의를 잊지 않아요."
L["Thank you, {name}. The voices approve of you, which is frankly alarming."] = "고마워요, {name}. 속삭임들까지 마음에 들어 하네요. 솔직히 좀 불안해요."
L["Thank you, {name}. Few give gifts to someone who glows this ominously."] = "고마워요, {name}. 이렇게 불길하게 빛나는데 선물이라니, 드문 일이에요."
L["Kindness is rare in the Void, {name}. I'll return yours before it notices."] = "공허에선 친절이 귀해요, {name}. 공허가 눈치채기 전에 얼른 갚을게요."
L["Silvermoon threw us out, {name}. People like you make it hard to mind."] = "실버문은 우릴 쫓아냈죠, {name}. 이런 분들 덕에 아쉬울 게 없네요."
L["Returned in full, {name}. It may be slightly purple. That's normal."] = "고스란히 갚았어요, {name}. 살짝 보랏빛일 수 있어요. 정상이에요."
L["The Void only takes, {name}. I, however, give back."] = "공허는 빼앗기만 하죠, {name}. 하지만 저는 돌려드려요."
L["As you wish, {name}. The shadows answer kindly today."] = "원하는 대로, {name}. 오늘은 그림자도 순순히 응하네요."
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "맡겨 둬요, {name}. 공허는 우리를 따르지, 그 반대가 아니에요."
L["Certainly, {name}. The whispers said no, so it's an easy yes."] = "그럼요, {name}. 속삭임들이 하지 말래서, 고민할 것도 없어요."
L["Of course, {name}. One {buff}, lightly seasoned with the Void."] = "물론이죠, {name}. 공허로 살짝 간을 한 {buff} 하나요."
L["Of course, {name}. Hold still; the shadows are shy with strangers."] = "물론이죠, {name}. 가만히요. 그림자가 낯을 가려서."
L["Gladly, {name}. Ren'dorei manners: the Void waits its turn."] = "기꺼이요, {name}. 렌도레이 예절이죠. 공허는 줄 서서 기다려요."
L["Asked so nicely, {name}? The Void never says please. Here."] = "이렇게 공손하게요, {name}? 공허는 부탁할 줄 모르거든요. 여기요."
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "{name}, 그림자를 살짝 드릴게요. 안전해요. 대체로요."
L["Walk carefully in the dark places, {name}."] = "어둠 속에선 발밑을 조심해요, {name}."
L["A little something from the Telogrus Rift, {name}. It's cleaner than it sounds."] = "텔로그루스 균열에서 온 작은 선물이에요, {name}. 생각보다 깨끗해요."
L["Take this, {name}. Any tentacles you see are purely decorative."] = "받아요, {name}. 촉수가 보여도 그냥 장식이에요."
L["The shadows asked after you, {name}. I told them to mind their manners."] = "그림자들이 안부를 묻더군요, {name}. 매너 좀 지키라고 했어요."
L["Here, {name}. We walked into the Void so you wouldn't have to."] = "여기요, {name}. 공허엔 우리가 대신 들어갔으니, 안 가셔도 돼요."
L["I checked your shadow, {name}. Nothing lurking. Take this anyway."] = "그림자를 살펴봤는데, {name}, 숨은 건 없네요. 그래도 받아요."
L["Umbric sends his regards, {name}. He doesn't, but he would."] = "엄브릭이 안부 전하래요, {name}. 그런 말은 안 했지만, 했을 거예요."
L["We ren'dorei look after our own, {name}."] = "우리 렌도레이는 동족을 챙기죠, {name}."
L["Silvermoon's loss, {name}. We're doing splendidly without it."] = "실버문만 손해죠, {name}. 우린 없어도 아주 잘 지내요."
L["Your whispers and mine should really meet sometime, {name}."] = "우리 속삭임들끼리 언제 한번 인사시켜요, {name}."
L["Two ren'dorei in one place, {name}. Quick, look brooding. It's expected."] = "렌도레이가 둘이나, {name}. 얼른 음울한 표정 지어요. 다들 기대하니까."
L["Stay close, {name}. The whispers are much quieter in company."] = "곁에 있어요, {name}. 함께 있으면 속삭임이 훨씬 조용해요."
L["If the shadows start giving orders, {name}, ignore them. I usually do."] = "그림자가 명령하기 시작하면, {name}, 무시해요. 저도 보통 그래요."
L["Keep an eye on my shadow, {name}. It wanders off when there's a fight."] = "제 그림자 좀 봐 줘요, {name}. 싸움만 나면 딴 데로 새거든요."
L["If I start glowing purple, {name}, carry on. It only means I'm keen."] = "제가 보랏빛으로 빛나도, {name}, 신경 쓰지 마요. 의욕이 넘쳐서 그래요."
L["We ren'dorei make fine companions, {name}. We bring our own dark to hide in."] = "렌도레이는 좋은 동료예요, {name}. 숨을 어둠을 직접 챙겨 오거든요."
L["Night suits the ren'dorei, {name}. We match the decor."] = "밤은 렌도레이와 잘 어울려요, {name}. 인테리어랑 깔맞춤이죠."
L["The shadows are longest now, {name}, and in a very generous mood."] = "지금 그림자가 가장 길어요, {name}. 마음씨도 가장 넉넉하고요."
L["Late, {name}? The whispers love a late hour. Lately, so do I."] = "늦었냐고요, {name}? 속삭임은 밤늦게 수다스러워지죠. 요즘은 저도요."
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "고마워요, {name}님! 호의 수신, 분류, 반송 완료!"
L["Reciprocity engaged! Much obliged, {name}."] = "상호 호혜 모드 가동! 감사해요, {name}님."
L["By my calculations, {name}, you're owed exactly one {buff}."] = "계산해 보니, {name}님께 정확히 {buff} 하나를 드려야 하네요."
L["Thanks, {name}! I'd build you a thank-you machine, but it'd explode."] = "고마워요, {name}님! 감사 기계를 만들어 드리고 싶지만, 터질 거예요."
L["Thank you, {name}! This calls for a celebration. Stand back, I'll build one."] = "고마워요, {name}님! 축하해야겠어요. 물러서세요, 하나 조립할게요."
L["You're too kind, {name}! Returning the favour took only four schematics."] = "너무 친절하세요, {name}님! 보답하는 데 설계도 네 장밖에 안 들었어요."
L["Drat, {name}! I was going to invent gratitude, but you beat me to it."] = "이런, {name}님! '고마움'을 발명하려던 참인데 선수를 치셨네요."
L["Oh, {name}, how kind! My heart's doing that whirring thing again."] = "어머, {name}님, 친절하셔라! 심장이 또 윙윙 돌아가요."
L["Request received, {name}! Processing... done!"] = "요청 접수, {name}님! 처리 중... 끝!"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "업그레이드 하나 나갑니다, {name}님! 보정할 테니 가만히!"
L["Of course, {name}! I built a machine for this. It's in pieces, so: by hand."] = "물론이죠, {name}님! 이거 하는 기계도 만들었는데, 박살 나서 손으로 할게요."
L["Certainly, {name}! Stand on the X. There's no X. Stand anywhere."] = "그럼요, {name}님! X 표시에 서세요. X가 없네요. 아무 데나 서세요."
L["Right away, {name}! Goggles on. Not for you, I just like them."] = "바로 할게요, {name}님! 고글 착용! 필요는 없고, 그냥 좋아서요."
L["{buff}, {name}? Simple in theory AND practice. Suspicious!"] = "{buff} 말이죠, {name}님? 이론도 실전도 간단하다니. 수상해요!"
L["Happy to, {name}! Keep hands, feet and eyebrows well clear."] = "기꺼이요, {name}님! 손발이랑 눈썹은 멀찍이 떨어뜨리세요."
L["Hold still, {name}, this is perfectly safe. Probably!"] = "가만히 계세요, {name}님. 완벽하게 안전해요. 아마도요!"
L["Science says you need this, {name}. Who am I to argue?"] = "과학이 필요하다잖아요, {name}님. 제가 어쩌겠어요?"
L["A small upgrade for you, {name}. No cogs required."] = "{name}님께 작은 업그레이드! 톱니바퀴는 필요 없어요."
L["Take it, {name}, I've a spare. I've three spares of everything."] = "받으세요, {name}님. 여분 있어요. 전 뭐든 여분이 세 개씩 있거든요."
L["Try this, {name}! Version one had legs. Version two is much better."] = "써 보세요, {name}님! 1호기엔 다리가 달렸었는데, 2호기가 훨씬 나아요."
L["The High Tinker says share our genius, {name}. Here's a sample!"] = "대땜장이님이 천재성을 나누랬어요, {name}님. 샘플 드릴게요!"
L["Gnomeregan Forever, {name}! This lasts rather less, but it's free."] = "놈리건이여 영원하라, {name}님! 이건 영원까진 아니지만 공짜예요."
L["I'm small, {name}, but my gifts come full-sized. Here!"] = "전 작아도, {name}님, 선물은 풀사이즈예요. 받으세요!"
L["Don't worry, {name}! It worked on the chicken, and the chicken's thrilled."] = "걱정 마세요, {name}님! 닭한테 써 봤는데, 닭이 아주 신났어요."
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "놈리건을 위하여, {name}님! 눈높이 맞는 상대라 반가워요."
L["A fellow gnome, {name}! I'll hold the schematic; you hold the bucket."] = "노움 동지네요, {name}님! 설계도는 제가 들게요, 양동이는 부탁해요."
L["Flesh or cogs, {name}, we're all gnomes. Some of us just need oiling."] = "살이든 톱니든, {name}님, 우린 다 노움이에요. 기름칠이 필요할 뿐."
L["One gnome to another, {name}: you did turn the reactor off, didn't you?"] = "노움끼리 묻는 건데요, {name}님. 원자로는 끄고 오셨죠?"
L["Party-wide calibration complete, {name}! Nobody touch anything shiny."] = "파티 전체 보정 완료예요, {name}님! 반짝이는 건 아무도 만지지 마세요."
L["I've run the numbers, {name}: with you here, we win. I rounded up."] = "계산해 봤는데요, {name}님. 우리가 이겨요. 반올림했지만요."
L["If I shout 'duck', {name}, don't look for a duck. That went badly last time."] = "제가 '앉아!' 하면, {name}님, 의자 찾지 마세요. 지난번에 큰일 났어요."
L["Formation, {name}: tall folk at the front, me somewhere safe and clever."] = "대형은요, {name}님. 키 큰 분들은 앞, 저는 안전하고 똑똑한 어딘가."
L["Everyone gets one, {name}! Standardised parts are the secret of a good machine."] = "하나씩 다 드려요, {name}님! 좋은 기계의 비결은 표준 부품이죠."
L["Morning, {name}! Up since three. The toaster needed a new engine."] = "좋은 아침, {name}님! 세 시부터 깼어요. 토스터에 엔진 새로 다느라."
L["Good morning, {name}! The coffee's brewing itself. It learned how. Worrying."] = "좋은 아침이에요, {name}님! 커피가 혼자 내려져요. 스스로 터득했대요. 불안해요."
L["Early start, {name}! Best ideas come before breakfast. So do the explosions."] = "일찍 시작하시네요, {name}님! 좋은 아이디어는 아침 전에 와요. 폭발도요."
L["The Light rewards kindness, {name}. I'm simply its fastest courier."] = "빛은 친절에 보답합니다, {name}. 저는 가장 빠른 배달부일 뿐이지요."
L["Archenon poros, {name}. Your gift is returned."] = "Archenon poros, {name}. 받은 선물을 돌려드립니다."
L["Thanks, {name}. I'd offer a lift in the Exodar, but you've seen how it lands."] = "감사합니다, {name}. 엑소다르에 태워 드리고 싶지만, 착륙하는 꼴을 보셨지요."
L["A gift freely given, {name}. The naaru hum a little louder. Returned."] = "아낌없는 선물이군요, {name}. 나루의 노래가 조금 커졌습니다. 보답하지요."
L["Kindly done, {name}. On Argus we'd have carved that in crystal. Here."] = "고맙습니다, {name}. 아르거스였다면 수정에 새겼을 겁니다. 받으십시오."
L["Across a dozen worlds, {name}, kindness is the one tongue I never had to learn."] = "수많은 세계를 떠돌았지만, {name}, 친절만은 배울 필요 없는 언어였습니다."
L["What a kindness, {name}. It almost makes up for the Legion. Almost."] = "이런 친절이라니, {name}. 군단 일이 거의 잊힐 정도입니다. 거의요."
L["Thank you, {name}. I'd say it in Draenei, but that takes eleven minutes."] = "감사합니다, {name}. 드레나이어로 하면 11분이 걸려서요."
L["Of course, {name}. The naaru guide your steps; this puts a spring in them."] = "물론입니다, {name}. 나루께선 길을, 저는 발걸음을 가볍게."
L["Gladly, {name}. The Light answers those who ask."] = "기꺼이, {name}. 빛은 구하는 이에게 응답합니다."
L["Velen foresaw you asking, {name}. I foresaw saying yes."] = "벨렌께선 청하실 걸 예견하셨지요, {name}. 저는 승낙을 예견했고요."
L["The Light is not rationed, {name}. Take as much as you like."] = "빛은 배급제가 아닙니다, {name}. 마음껏 받으십시오."
L["Of course, {name}. I've outrun the Burning Legion; I can manage this."] = "물론입니다, {name}. 불타는 군단한테서도 도망쳤는데, 이쯤이야."
L["At once, {name}. Hooves planted, crystals humming, here it comes."] = "즉시 하지요, {name}. 발굽 고정, 수정 공명, 갑니다."
L["Gladly, {name}. I followed a talking crystal across the stars. This is easy."] = "기꺼이요, {name}. 말하는 수정을 따라 별을 건넜는데, 이쯤은 쉽지요."
L["The Light is with you, {name}. Go in peace, or at least go prepared."] = "빛이 그대와 함께합니다, {name}. 평안히 가십시오. 안 되면 대비라도 하고."
L["Walk in the Light, {name}. May it shelter you always."] = "빛 속을 걸으십시오, {name}. 빛이 늘 그대를 지켜 주기를."
L["Take this, {name}. My people always travel Light."] = "받으십시오, {name}. 우린 가진 게 빛뿐이라 짐이 늘 가볍지요."
L["Take this, {name}. The Legion is always coming. I'd know."] = "받으십시오, {name}. 군단은 늘 옵니다. 제가 잘 알지요."
L["I'm out of miracles today, {name}. Will {buff} do?"] = "오늘치 기적은 다 썼습니다, {name}. 대신 {buff}, 괜찮겠습니까?"
L["For the road, {name}. Mine has been twenty-five thousand years long."] = "가는 길에 쓰십시오, {name}. 제 길은 2만 5천 년째입니다."
L["Blessed by a naaru, {name}. Well, I stood near one. It still counts."] = "나루의 축복입니다, {name}. 음, 나루 옆에 서 있었지요. 그것도 치는 겁니다."
L["Take this, {name}. It glows a bit. Everything we own does."] = "받으십시오, {name}. 좀 빛납니다. 우리 물건은 다 그렇지요."
L["Archenon poros, {name}! The children of Argus look after one another."] = "Archenon poros, {name}! 아르거스의 자손은 서로를 돌보지요."
L["Home is wherever two draenei meet, {name}. Today, it's here."] = "드레나이 둘이 만나는 곳이 곧 고향이지요, {name}. 오늘은 여기입니다."
L["Horns high, {name}. Two draenei, and nobody's mentioned the Legion. Progress."] = "뿔을 높이, {name}. 드레나이가 둘인데 아무도 군단 얘길 안 꺼냈군요. 발전입니다."
L["Tails up, {name}. Argus would be proud of what we've made of exile."] = "꼬리를 세우십시오, {name}. 아르거스가 봐도 자랑스러운 망명이지요."
L["Stay near, {name}. I lost a world once; I'm keeping hold of this party."] = "곁에 계십시오, {name}. 세계를 한 번 잃었으니, 이 파티만은 꼭 붙잡겠습니다."
L["Twenty-five thousand years on the run, {name}. Walking with friends is nicer."] = "2만 5천 년을 도망쳤지요, {name}. 벗들과 걷는 게 훨씬 낫습니다."
L["The naaru would call this a fellowship, {name}. I call it good luck."] = "나루께선 이걸 동행이라 하시겠지요, {name}. 저는 행운이라 부릅니다."
L["I've watched worlds end, {name}. Whatever's ahead of us hardly worries me."] = "세계가 끝나는 것도 봤습니다, {name}. 앞에 뭐가 있든 걱정 없습니다."
L["Stay together, {name}. The Light finds us easier when we're all in one place."] = "뭉쳐 다닙시다, {name}. 한데 모여 있어야 빛이 찾기 쉽지요."
L["Much obliged, {name}. Gilneas never forgets a kindness, and nor does my nose."] = "신세 졌소, {name}. 길니아스는 은혜를 잊지 않소. 내 코도 그렇고."
L["Thank you, {name}. You have my gratitude, and my best howl."] = "고맙소, {name}. 감사의 마음과 회심의 울음소리를 바치오."
L["Thank you, {name}. If worgen had tails, mine would be wagging."] = "고맙소, {name}. 늑대인간에게 꼬리가 있었다면 지금 흔들고 있을 거요."
L["You've made a friend for life, {name}. Loyalty is rather our thing."] = "평생 친구가 생겼구려, {name}. 충성은 우리 특기라오."
L["The beast in me wants to growl, {name}. The Gilnean in me insists on thanks."] = "내 안의 짐승은 으르렁대라 하고, 길니아스인은 감사하라 하는군, {name}."
L["Much appreciated, {name}. I'd shake your hand, but, claws. Here instead."] = "고맙소, {name}. 악수하고 싶지만, 발톱이 있어서. 대신 이걸 받으시오."
L["We walled ourselves off for years, {name}. You make that look silly."] = "성벽 쌓고 숨어 산 세월이 우스워지는군, {name}. 그대 덕에."
L["Obliged, {name}. You've earned a spot by the fire. The good spot."] = "고맙소, {name}. 난롯가 자리를 드리리다. 제일 좋은 자리로."
L["Certainly, {name}. Hold still, I don't bite. Much."] = "그러리다, {name}. 가만히 계시오. 물지 않소. 세게는."
L["Right you are, {name}. Stand steady now."] = "좋소, {name}. 자, 흔들리지 말고 서 계시오."
L["Right away, {name}. Stay, now. I've always wanted to say that."] = "바로 하리다, {name}. 자, '기다려.' 늘 해 보고 싶던 말이오."
L["Gladly, {name}. Rain or shine, and in Gilneas it's rain."] = "기꺼이, {name}. 비가 오든 해가 뜨든. 길니아스에선 늘 비지만."
L["Certainly, {name}. I'll try not to shed on you."] = "그러리다, {name}. 털 안 날리게 조심하겠소."
L["Say no more, {name}. These ears heard you before you'd decided to ask."] = "말할 것 없소, {name}. 청하기로 마음먹기도 전에 이 귀가 들었소."
L["Of course, {name}. You asked nicer than the last fellow who threw me a stick."] = "물론이오, {name}. 지난번에 막대기 던진 녀석보다 훨씬 정중하구려."
L["Stay off the moors after dark, {name}. Take this."] = "해 지면 황야엔 가지 마시오, {name}. 이걸 받으시오."
L["Keep your wits about you, {name}. Something is always hunting."] = "정신 바짝 차리시오, {name}. 늘 뭔가가 사냥 중이니."
L["I'd have brought this sooner, {name}, but I stopped to chase something."] = "더 일찍 가져오려 했소, {name}. 뭘 좀 쫓느라 늦었지만."
L["For you, {name}. No, I don't want a treat. Well. Perhaps a small one."] = "받으시오, {name}. 아니, 간식은 필요 없소. 음. 작은 거라면 몰라도."
L["Gilneans always offer, {name}. The claws are just part of the outfit."] = "길니아스인은 늘 먼저 베푸오, {name}. 발톱은 그냥 옷차림의 일부요."
L["An old Gilnean remedy, {name}. Good for colds, gloom and most curses. Not mine."] = "길니아스 전통 비방이오, {name}. 감기, 우울, 웬만한 저주에 좋소. 내 건 빼고."
L["Run with this, {name}. Trust me, I know about running."] = "이걸 갖고 달리시오, {name}. 달리기라면 내가 좀 알지."
L["Fetched this for you, {name}. Don't make a thing of it."] = "물어 왔소, {name}. 호들갑 떨지 마시오."
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "저주보다 길니아스가 우릴 더 단단히 묶는다오, {name}."
L["No need to explain the ears to you, {name}."] = "그대에겐 이 귀를 설명할 필요가 없겠구려, {name}."
L["Fur, fog and rain, {name}. Only a Gilnean understands all three."] = "털, 안개, 비, {name}. 셋 다 이해하는 건 길니아스인뿐이오."
L["Pack looks after pack, {name}. Always has."] = "무리는 무리를 챙기는 법이오, {name}. 늘 그래 왔소."
L["Pack rules, {name}: nobody wanders off, and nobody mentions the fleas."] = "무리 규칙이오, {name}. 아무도 떨어지지 말 것. 벼룩 얘기는 금지."
L["A pack again, {name}. I hadn't known how much I'd missed one."] = "다시 무리가 생겼구려, {name}. 이렇게 그리웠는지 몰랐소."
L["I'll catch the scent of trouble first, {name}. It's the one perk of the curse."] = "위험 냄새는 내가 먼저 맡으리다, {name}. 저주의 유일한 장점이오."
L["If I howl, {name}, it's a battle cry. Probably. Don't look at me like that."] = "내가 울부짖으면, {name}, 함성이오. 아마도. 그런 눈으로 보지 마시오."
L["Lead on, {name}. I'll trot. It's undignified, but it's much quicker."] = "앞장서시오, {name}. 난 네 발로 뛰겠소. 체면은 없어도 훨씬 빠르오."
L["Night again, {name}. I'm at my best and my worst. This is the best part."] = "또 밤이구려, {name}. 내가 가장 좋고도 가장 나쁠 때요. 이건 좋은 쪽이오."
L["Look at that moon, {name}. Don't mind me; I'm not howling. Much."] = "저 달 좀 보시오, {name}. 신경 쓰지 마시오. 안 울부짖소. 많이는."
L["Gilneas at night was fog and footsteps, {name}. These days I'm the footsteps."] = "밤의 길니아스는 안개와 발소리뿐이었소, {name}. 요즘은 내가 그 발소리요."
L["Morning, {name}. I'd have been up sooner, but the rug by the fire was so warm."] = "좋은 아침이오, {name}. 더 일찍 일어났을 텐데, 난롯가 깔개가 너무 따뜻해서."
L["Smells like rain this morning, {name}. Everything in Gilneas smelled like rain."] = "아침부터 비 냄새가 나는군, {name}. 길니아스는 뭐든 비 냄새가 났지."
L["Up already, {name}? I've chased two rabbits. For exercise. Purely."] = "벌써 일어났소, {name}? 난 토끼 두 마리를 쫓았소. 운동 삼아. 순전히."
L["Throm-ka, {name}! Honour is repaid."] = "Throm-ka, {name}! 명예로 갚는다!"
L["You give freely, {name}. I return the favour."] = "선뜻 베풀었군, {name}. 나도 갚아 주지."
L["Orcs keep their thanks short, {name}. Thanks."] = "오크는 감사도 짧다, {name}. 고맙다."
L["Orcs return every blow twice, {name}. The kind ones too."] = "오크는 한 대 맞으면 두 대로 갚는다, {name}. 호의도 마찬가지다."
L["You helped me, I help you. Orc poetry, {name}. It doesn't rhyme."] = "네가 도왔으니, 나도 돕는다. 오크의 시다, {name}. 운율은 없다."
L["In the old days I'd have repaid you with a boar, {name}. This keeps better."] = "옛날 같으면 멧돼지로 갚았겠지, {name}. 이건 안 썩는다."
L["Owing somebody itches worse than Durotar sand, {name}. There. Itch gone."] = "빚지면 듀로타 모래보다 더 근질거린다, {name}. 됐다. 이제 안 가렵다."
L["Strong stuff, {name}. I could wrestle a kodo now. So can you."] = "센 거로군, {name}. 코도랑 씨름도 하겠다. 너도 이제 된다."
L["Dabu, {name}. It is done."] = "Dabu, {name}. 다 됐다."
L["Hold still, {name}. Strength for the fight ahead."] = "가만있어라, {name}. 다가올 싸움을 위한 힘이다."
L["Ask an orc for help and you get it, {name}. Ask for subtlety and you wait."] = "오크한테 도움을 청하면 바로 준다, {name}. 섬세함을 청하면 기다려야 하고."
L["Help, yes. Hugging, no. Hold still, {name}."] = "도움은 준다. 포옹은 안 한다. 가만있어라, {name}."
L["You want {buff}? You have {buff}, {name}. Next."] = "{buff} 원하나, {name}? 옜다, {buff}. 다음."
L["Don't flinch, {name}. My helping face looks exactly like my fighting face."] = "움찔하지 마라, {name}. 돕는 얼굴이 싸우는 얼굴이랑 똑같을 뿐이다."
L["Short question, short answer, {name}: yes."] = "짧은 질문엔 짧은 대답이다, {name}. 그래."
L["Lok'tar ogar, {name}! Take this into battle. A tavern brawl also counts."] = "Lok'tar ogar, {name}! 이걸 품고 전장으로 가라. 술집 싸움도 전장이다."
L["Blood and thunder, {name}! Go and earn your glory."] = "피와 천둥이여, {name}! 가서 영광을 쟁취해라!"
L["Among orcs, {name}, making you stronger is how we say we like you."] = "오크들 사이에선, {name}, 강하게 만들어 주는 게 좋아한다는 뜻이다."
L["An orc giving gifts unasked? Tell no one, {name}. It ruins the image."] = "오크가 먼저 선물을 줬다고? 아무한테도 말하지 마라, {name}. 이미지 망친다."
L["I was told to be more diplomatic, {name}. This is me being diplomatic."] = "외교적으로 굴라더군, {name}. 이게 내 외교다."
L["Go hit something for me, {name}. Or set it on fire. Orcs aren't fussy."] = "가서 뭐든 한 대 때려라, {name}. 아니면 불태우든가. 오크는 안 가린다."
L["Don't thank me, {name}. Just win, and do it loudly."] = "고마워하지 마라, {name}. 이기기만 해라. 요란하게."
L["I'd make a speech, {name}, but it's mostly shouting. Just take it."] = "연설이라도 하고 싶지만, {name}, 대부분 고함이다. 그냥 받아라."
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "Throm-ka, {name}! 네 안에 부족의 피가 힘차게 흐르는군."
L["An orc, {name}! Finally, somebody who shouts at my volume."] = "오크로군, {name}! 드디어 나랑 목청이 맞는 녀석이다."
L["Frostwolf, Warsong or Blackrock, {name}, we all argue like family."] = "서리늑대든 전쟁노래든 검은바위든, {name}, 싸우는 건 다 가족 같다."
L["Between orcs no words are needed, {name}. Good. I was out of them."] = "오크끼리는 말이 필요 없다, {name}. 다행이다. 할 말도 떨어졌다."
L["The plan, {name}: we hit it. Questions? No? Good plan."] = "작전이다, {name}. 때린다. 질문? 없나? 좋은 작전이다."
L["A true warband, {name}. Loud, angry, and all on the same side for once."] = "진짜 전투부대다, {name}. 시끄럽고, 성났고, 웬일로 다 한편이다."
L["Stay with the warband, {name}. Strength in numbers. And in axes."] = "부대에서 떨어지지 마라, {name}. 힘은 머릿수에서 나온다. 도끼 수에서도."
L["If you fall, {name}, I carry you out. Complaining the whole way, but I carry."] = "쓰러지면, {name}, 내가 업고 나간다. 내내 투덜대겠지만, 업는다."
L["Fight well, {name}, and tonight you share our fire. And our boasting."] = "잘 싸우면, {name}, 오늘 밤 우리 모닥불에 끼워 주마. 허풍도 같이."
L["Thank you, {name}. It would warm my heart, if it still beat."] = "고맙군, {name}. 심장이 아직 뛴다면 따뜻해졌을 텐데."
L["Such warmth, for one so cold? Returned in full, {name}."] = "이리 차가운 자에게 온기라니? 고스란히 돌려주지, {name}."
L["Thank you, {name}. I'd blush, but the blood stopped reaching my face."] = "고맙군, {name}. 얼굴이라도 붉히고 싶지만, 피가 거기까지 안 올라가서."
L["My undying gratitude, {name}. For once, the phrase is accurate."] = "죽어도 잊지 못할 은혜요, {name}. 이번만은 말 그대로요."
L["Most kind, {name}. You've lifted me from 'deceased' to 'mildly deceased'."] = "친절하군, {name}. 덕분에 '사망'에서 '약간 사망'이 됐소."
L["You've added years to my life, {name}. Shame it already ended."] = "수명이 몇 년은 늘었군, {name}. 이미 끝난 수명이라 아쉽지만."
L["I felt that, {name}, and I don't feel much these days. Here, feel this."] = "느껴지는군, {name}. 요즘 느끼는 게 별로 없는데. 자, 이것도 느껴 보시오."
L["I'd shake your hand, {name}, but I'm not sure mine is still attached."] = "악수라도 하고 싶지만, {name}, 내 손이 아직 붙어 있는지 모르겠군."
L["Certainly, {name}. Try not to die. It's overrated."] = "그러지, {name}. 죽지는 마시오. 생각보다 별거 없으니."
L["You need only ask, {name}. The dead are patient."] = "말만 하시오, {name}. 죽은 자는 인내심이 많으니."
L["Ask the dead for a favour, {name}. We rarely have other plans."] = "부탁은 죽은 자에게 하시오, {name}. 우린 딱히 다른 약속이 없거든."
L["Certainly, {name}. Stand clear; I'd hate to drop anything on you."] = "그러지, {name}. 좀 떨어지시오. 뭐가 떨어지기라도 하면 곤란하니."
L["A moment, {name}. Rigor mortis is hard on the casting hand."] = "잠깐, {name}. 사후 경직 때문에 시전하는 손이 뻣뻣해서."
L["Nice to be asked for something, {name}, besides the way to the graveyard."] = "무덤 가는 길 말고 다른 걸 물어 주니 반갑군, {name}."
L["Gladly, {name}. It takes my mind off the smell. Mine, I mean."] = "기꺼이, {name}. 냄새 생각을 잊게 해 주니까. 내 냄새 말이오."
L["Stay among the living a little longer, {name}."] = "산 자들 곁에 조금 더 머무시오, {name}."
L["Take this, {name}. The grave can wait."] = "받으시오, {name}. 무덤은 기다려 줄 거요."
L["I was a physician in Lordaeron, {name}. Old habits die harder than I did."] = "로데론에선 의사였소, {name}. 버릇은 나보다 끈질기게 안 죽더군."
L["No charge, {name}. The apothecaries would have made you sign something."] = "공짜요, {name}. 약제사들이었으면 뭔가에 서명부터 시켰을 거요."
L["A gift from the grave, {name}. Don't worry, I washed it."] = "무덤에서 온 선물이오, {name}. 걱정 마시오, 씻어 왔으니."
L["Every body needs a little help, {name}. Mine mostly needs stitches."] = "몸 가진 자라면 다 도움이 필요하오, {name}. 내 몸은 주로 바느질이지만."
L["I've seen where heroes end up, {name}. I live there. Take this."] = "영웅들이 결국 어디로 가는지 봤소, {name}. 내가 사는 곳이오. 받으시오."
L["Take this, {name}. I learned the hard way you can't take it with you."] = "받으시오, {name}. 저승엔 못 가져간다는 걸 몸소 배웠소."
L["We Forsaken must look after each other, {name}."] = "우리 포세이큰끼리는 서로 챙겨야지, {name}."
L["Between us corpses, {name}, you're remarkably well preserved."] = "시체끼리 하는 말인데, {name}, 보존 상태가 아주 훌륭하구려."
L["Lose a finger, {name}, and I've a spare. Forsaken share."] = "손가락 떨어지면 말하시오, {name}. 여분 있소. 포세이큰은 나누는 법."
L["Is your jaw clicking too, {name}, or is that just me?"] = "{name}, 그대도 턱에서 딸깍 소리가 나오, 아니면 나만 그렇소?"
L["Stay alive, {name}. I've tried the alternative, and I can't recommend it."] = "살아 있으시오, {name}. 반대쪽도 해 봤는데, 추천은 못 하겠소."
L["If I fall down, {name}, give it a minute. Old habit."] = "내가 쓰러져도, {name}, 잠깐 기다리시오. 오랜 버릇이라."
L["I'll take the front, {name}. What's the worst that could happen? Again?"] = "앞은 내가 맡지, {name}. 최악이래 봐야 뭐겠소? 또 죽는 거?"
L["Keep upwind of me, {name}. It's better for morale."] = "내 바람 위쪽에 서시오, {name}. 사기에 좋으니."
L["The last party I joined, {name}, I woke up in a crypt. Let's improve on that."] = "지난번 파티에선, {name}, 깨어나 보니 지하 묘지였소. 이번엔 좀 낫게 해 봅시다."
L["The dead keep terrible hours, {name}. Nice to have company for once."] = "죽은 자들은 생활 리듬이 엉망이오, {name}. 모처럼 말동무가 있어 좋군."
L["Midnight, {name}: the best hour to be up and about when you shouldn't be."] = "자정이오, {name}. 일어나 있으면 안 될 자가 돌아다니기 딱 좋은 시간."
L["The living are all asleep, {name}. We Forsaken call this the quiet shift."] = "산 자들은 다 잠들었소, {name}. 포세이큰은 이걸 조용한 야간 근무라 부르지."
L["Morning already, {name}? I've been up all night. And all of last decade."] = "벌써 아침이오, {name}? 밤을 꼬박 새웠소. 지난 십 년도."
L["The sun's up, {name}. I'll stand in the shade, if you don't mind. Things peel."] = "해가 떴군, {name}. 그늘에 서 있겠소. 이것저것 벗겨져서."
L["Early start, {name}. The dead never sleep in. Or at all, really."] = "이른 출발이군, {name}. 죽은 자는 늦잠을 안 자오. 사실 잠 자체를."
L["The Earth Mother saw your kindness, {name}. She nudged me. Quite hard."] = "대지모신께서 그대의 친절을 보셨소, {name}. 날 쿡 찌르시더군. 꽤 세게."
L["Thank you, {name}. May the winds guide you."] = "고마운 일이오, {name}. 바람이 그대를 이끌기를."
L["Thank you, {name}. I'm deeply moved, and it takes a lot to move a tauren."] = "고맙소, {name}. 마음이 움직였소. 타우렌을 움직이기란 쉽지 않은데."
L["It's a long way up to a tauren's heart, {name}. You found it."] = "타우렌의 심장까진 한참 올라가야 하오, {name}. 그대가 찾아냈구려."
L["I felt that from horn to hoof, {name}. Returned, hoof to horn."] = "뿔부터 발굽까지 느꼈소, {name}. 발굽부터 뿔까지 돌려드리리다."
L["A gift given is a seed planted, {name}. Here is the harvest."] = "베푼 선물은 심은 씨앗이오, {name}. 여기 그 수확이오."
L["That deserves a feast, {name}. The feast can wait; {buff} can't."] = "잔치를 열 일이오, {name}. 잔치는 나중에, {buff} 먼저."
L["Thank you, {name}. Should you ever need a wall to hide behind, I'm free."] = "고맙소, {name}. 숨을 벽이 필요하면 말하시오. 난 늘 한가하오."
L["Of course, {name}. Stand tall and be at peace. I'll handle the tall part."] = "여부가 있겠소, {name}. 마음 편히 계시오. 우뚝 서는 건 내가 하리다."
L["Ask and it is given, {name}. The herd shares what it has."] = "청하면 주는 법이오, {name}. 무리는 가진 것을 나누니."
L["Of course, {name}. Stand back a pace; I do this with my whole body."] = "물론이오, {name}. 한 걸음 물러서시오. 난 온몸으로 하니까."
L["Gladly, {name}. Mind the tail."] = "기꺼이, {name}. 꼬리 조심하시오."
L["The Earth Mother gives freely, {name}, and so do her largest children."] = "대지모신께선 아낌없이 주시오, {name}. 그분의 가장 큰 자식들도 그렇고."
L["Gladly, {name}. Tauren are slow to anger and quick to help. Quick-ish."] = "기꺼이, {name}. 타우렌은 화는 느리고 돕기는 빠르오. 빠른 편이오."
L["Refuse you, {name}? My ancestors would never let me hear the end of it."] = "거절이라니, {name}? 조상님들 잔소리를 영원히 들을 거요."
L["Walk with the Earth Mother, {name}. She's everywhere, so you can't get lost."] = "대지모신과 함께 걸으시오, {name}. 어디에나 계시니 길 잃을 일은 없소."
L["May An'she light your path, {name}."] = "안셰께서 그대의 길을 비추시기를, {name}."
L["You looked like you could use a friend, {name}. I'm a very big one."] = "친구가 필요해 보였소, {name}. 난 아주 큰 친구라오."
L["Take this, {name}. The Earth Mother would scold me if I walked past."] = "받으시오, {name}. 그냥 지나쳤다간 대지모신께 혼나오."
L["Tread lightly, {name}. Take it from someone who never has."] = "사뿐히 걸으시오, {name}. 평생 그래 본 적 없는 자의 조언이오."
L["The wind said you'd pass this way, {name}. The wind is a terrible gossip."] = "바람이 그대가 지나갈 거라 하더군, {name}. 바람은 입이 가볍소."
L["Take this, {name}. I'd lend you my kodo too, but he's less generous than me."] = "받으시오, {name}. 코도도 빌려주고 싶지만, 그 녀석은 나만큼 너그럽지 않소."
L["The shu'halo say carry what you can for others, {name}. I can carry a lot."] = "슈할로는 남을 위해 질 수 있는 만큼 지라 하오, {name}. 난 많이 질 수 있소."
L["The Earth Mother watches over us both, {name}."] = "대지모신께서 우리 둘을 지켜보신다오, {name}."
L["Somebody warn the doorframes, {name}. There are two of us now."] = "문틀들한테 경고 좀 해 주시오, {name}. 이제 우리가 둘이오."
L["Plains or peaks, {name}, a shu'halo heart is a big one."] = "평원이든 산이든, {name}, 슈할로의 심장은 크다오."
L["Horns and helmets, {name}. Only another tauren knows the pain."] = "뿔과 투구라, {name}. 이 고통은 타우렌만 알지."
L["Get behind me, {name}. There's room back there for the whole party."] = "내 뒤로 오시오, {name}. 파티 전체가 들어가고도 남소."
L["The herd moves together, {name}. Mind my hooves; the herd has learned to."] = "무리는 함께 움직이오, {name}. 내 발굽 조심하시오. 무리는 이미 배웠소."
L["Low ceilings ahead, {name}? I'll be the first to find out. Take this."] = "앞에 천장이 낮소, {name}? 제일 먼저 알게 될 건 나요. 받으시오."
L["I'm slow to anger, {name}, but I hold a grudge for the whole party."] = "난 쉽게 화내지 않소, {name}. 하지만 원한은 파티 몫까지 품지."
L["Need a wall to hide behind, {name}? I'm most of one. Come on."] = "숨을 벽이 필요하오, {name}? 내가 거의 벽이오. 오시오."
L["An'she rises, {name}, and so do we. Slower, in my case."] = "안셰께서 떠오르시오, {name}. 우리도 일어나야지. 난 좀 느리지만."
L["The sun is An'she's eye, {name}. He's watching, so let's look busy."] = "해는 안셰의 눈이오, {name}. 지켜보고 계시니 바쁜 척합시다."
L["Morning, {name}. The kodo are up, the grass is wet, and this is yours."] = "좋은 아침이오, {name}. 코도는 일어났고, 풀은 젖었고, 이건 그대 것이오."
L["Mu'sha keeps the night watch, {name}. I'll tell her to keep an eye on you."] = "무샤께서 밤을 지키시오, {name}. 그대를 잘 봐 달라고 말씀드리리다."
L["The moon's out, {name}. Mu'sha sees you, and she approves. I asked."] = "달이 떴소, {name}. 무샤께서 그대를 보시고 좋다 하시오. 내가 여쭤봤소."
L["Late, {name}. The kodo are asleep, and they snore like thunder. Take this."] = "밤이 깊었소, {name}. 코도들이 천둥처럼 코를 고는군. 받으시오."
L["Ya be too kind, {name}! Dis one be from me."] = "친절하기도 하지, {name}! 이건 내가 주는 거라고."
L["Thanks, mon! Da spirits smile on ya, {name}."] = "고맙다, 친구! 영혼들이 너한테 미소 짓는다고, {name}."
L["Ya gave me good mojo, {name}. Now ya get some back, extra spicy."] = "좋은 기운 줬으니, {name}, 매운맛으로 돌려준다고."
L["Bwonsamdi gonna be real disappointed, {name}. Thanks, mon."] = "브원삼디가 엄청 실망하겠네, {name}. 고맙다, 친구."
L["Dat be some fine work, {name}. Almost as fine as me. Almost."] = "솜씨 좋은데, {name}. 거의 나만큼. 거의."
L["A troll can grow back a hand, {name}. Can't grow back honour. Here."] = "트롤은 손이 다시 자란다고, {name}. 명예는 안 자라. 자, 갚는다."
L["Ya just made a troll smile, {name}, and we got a lot of teeth."] = "트롤을 웃게 만들었네, {name}. 우리 이빨 많다고."
L["Da loa keep a tally, {name}, and now ya on da good side of it."] = "로아가 장부를 적는다고, {name}. 이제 넌 좋은 쪽에 있어."
L["Sure ting, {name}. Hold still; da mojo don't like a movin' target."] = "암, 그렇고말고, {name}. 가만있어. 주술은 움직이는 과녁을 싫어한다고."
L["No worries, {name}. Da loa got ya covered."] = "걱정 마, {name}. 로아가 챙겨 줄 거라고."
L["Stay away from da voodoo, {name}. ...Except dis voodoo. Dis one fine."] = "부두는 가까이하지 마, {name}. ...이 부두만 빼고. 이건 괜찮다고."
L["Close ya eyes, {name}. Da mojo be shy when people watch."] = "눈 감아, {name}. 주술이 누가 보면 부끄럼 탄다고."
L["Ya don't gotta ask twice, {name}. Ya barely gotta ask once."] = "두 번 말할 필요 없어, {name}. 한 번도 겨우 필요하다고."
L["Sure, {name}. Bein' a troll be mostly swagger. Da rest be dis."] = "그래, {name}. 트롤은 대부분 허세라고. 나머진 이거고."
L["Ya asked real polite, {name}. Polite get da good stuff."] = "예의 바르게 물었네, {name}. 예의 바르면 좋은 걸 받는다고."
L["Da loa be watchin' over ya, {name}. Dey real nosy like dat."] = "로아가 널 지켜보고 있다고, {name}. 참견쟁이들이거든."
L["Stay sharp out dere, {name}. Take dis wit' ya."] = "눈 크게 뜨고 다니라고, {name}. 이거 챙겨 가."
L["Ya look like somebody who appreciate quality, {name}. Here: quality."] = "품질 좀 알아보게 생겼네, {name}. 자, 품질."
L["Take dis, {name}. Walk like ya own da jungle. I do."] = "이거 받아, {name}. 정글 주인처럼 걸으라고. 나처럼."
L["Everybody need mojo, {name}. I make so much I gotta give it away."] = "누구나 주술 기운이 필요하다고, {name}. 난 너무 많아서 나눠 줘야 해."
L["A little somethin' for ya, {name}. Don't ask where da loa got it."] = "작은 선물이다, {name}. 로아가 어디서 났는지는 묻지 마."
L["Go on, {name}. Anyting try to eat ya now gonna get indigestion."] = "가 봐, {name}. 이제 널 먹으려는 놈은 체할 거라고."
L["Ya lookin' dangerous now, {name}. Almost troll-level dangerous."] = "이제 좀 위험해 보이네, {name}. 거의 트롤급으로."
L["Hey, {name}! Always good to see family, mon."] = "어이, {name}! 가족을 보니 늘 반갑다고, 친구."
L["Da rest of Azeroth stand up straight, {name}. We got more style."] = "아제로스 딴 녀석들은 허리 펴고 선다고, {name}. 우리가 더 멋있지."
L["Hey, {name}, ya tusks be lookin' sharp. Mine too, obviously."] = "어이, {name}, 엄니 날 잘 섰는데. 내 것도 물론이고."
L["Every troll be family, {name}. Even da ones who still owe me gold."] = "트롤은 다 가족이라고, {name}. 아직 돈 안 갚은 녀석들까지."
L["Stay close, {name}. Trolls regenerate; da rest of ya gotta be careful."] = "붙어 있어, {name}. 트롤은 재생되지만, 너희는 조심해야 한다고."
L["Dis crew got style, {name}. Now it got mojo too."] = "이 패거리 멋있다고, {name}. 이제 주술 기운까지 있고."
L["We go in together, {name}, we come out together. Dat be da whole plan, mon."] = "같이 들어가서 같이 나온다, {name}. 그게 작전 전부라고, 친구."
L["Nobody fallin' today, {name}. Bwonsamdi can wait for da next group."] = "오늘은 아무도 안 쓰러진다고, {name}. 브원삼디는 다음 파티나 기다리라 해."
L["Keep ya head down, {name}. I keep mine up. Somebody gotta look good."] = "넌 고개 숙여, {name}. 난 들고 있을게. 누군간 멋있어야지."
L["Night be da best time for mojo, {name}. Nobody see where it come from."] = "밤이 주술엔 최고라고, {name}. 어디서 오는지 아무도 못 보거든."
L["Da jungle wake up at night, {name}. So do I. Here, dis one fresh."] = "정글은 밤에 깨어난다고, {name}. 나도. 자, 갓 뽑은 거다."
L["Moon be high, {name}, spirits be restless. Dis keep dem off ya."] = "달이 높다, {name}. 영혼들이 들썩인다고. 이게 막아 줄 거야."
L["Such courtesy does you credit, {name}. Nearly as much as it does me."] = "그 예의, 그대를 빛내 주는군요, {name}. 날 빛내는 것만은 못해도."
L["How gracious, {name}. Allow me to return the favour."] = "품위 있는 행동이군요, {name}. 나도 호의로 답하지요."
L["Thank you, {name}. I haven't felt this radiant since... well, this morning."] = "고마워요, {name}. 이렇게 눈부신 기분은... 음, 오늘 아침 이후 처음이네요."
L["Kind of you, {name}. We sin'dorei never turn down free magic. Ask anyone."] = "친절하군요, {name}. 신도레이는 공짜 마법은 절대 사양 안 해요. 소문났죠."
L["Exquisite, {name}. I would know; I only accept the exquisite."] = "훌륭하군요, {name}. 난 훌륭한 것만 받으니 확실하죠."
L["Lovely, {name}. I'll be insufferable about this all day. More than usual."] = "근사하네요, {name}. 오늘 하루 종일 이걸로 으스댈 거예요. 평소보다 더."
L["Thank you, {name}. It even goes with my gold trim. You have an eye."] = "고마워요, {name}. 내 금장식과도 어울리네요. 안목이 있으시군요."
L["Returned in kind, {name}. A prettier kind, admittedly. I can't help it."] = "같은 걸로 보답하죠, {name}. 좀 더 예쁜 걸로요. 어쩔 수 없네요."
L["Naturally, {name}. Only the finest for you."] = "당연하지요, {name}. 그대에겐 최고만 드리죠."
L["For you, {name}? Of course. The sun gives freely."] = "{name}, 그대에게요? 물론이죠. 태양은 아낌없이 베푸니."
L["Patience, {name}. Radiance can't be rushed, only admired."] = "서두르지 마요, {name}. 광채는 재촉하는 게 아니라 감상하는 거예요."
L["Of course, {name}. {buff}, delivered with impeccable posture."] = "물론이죠, {name}. 흠잡을 데 없는 자세로 {buff} 대령이에요."
L["You asked nicely, {name}. In Silvermoon that counts for everything."] = "정중하게 청하셨군요, {name}. 실버문에선 그게 전부죠."
L["One moment, {name}. I never cast anything without checking my hair."] = "잠시만요, {name}. 머리 모양을 확인하지 않고는 아무것도 시전 안 해요."
L["At once, {name}. Keeping someone waiting is so terribly unfashionable."] = "당장 하죠, {name}. 남을 기다리게 하는 건 너무 촌스러우니까."
L["Anar'alah belore, {name}. May the sun guide you, and light your good side."] = "Anar'alah belore, {name}. 태양이 그대를 인도하고, 잘 나온 쪽을 비추기를."
L["Shorel'aran, {name}. Fight with elegance."] = "Shorel'aran, {name}. 우아하게 싸우시길."
L["Take this, {name}. Whatever happens out there is merely a setback."] = "받으세요, {name}. 밖에서 무슨 일이 생기든 잠깐의 후퇴일 뿐이에요."
L["Everyone deserves to shine, {name}. Only a little less than me, of course."] = "누구나 빛날 자격이 있죠, {name}. 물론 나보다 조금 덜."
L["The sun is with you, {name}. I simply held the door for it."] = "태양이 그대와 함께해요, {name}. 난 문만 열어 줬을 뿐이죠."
L["Go on, {name}, take it. The Sunwell's back; we can afford to be generous."] = "어서 받아요, {name}. 태양샘도 돌아왔으니 이 정도 인심은 쓰죠."
L["For you, {name}: {buff}, lightly scented with Silvermoon."] = "{name}, 그대에게. 실버문 향을 살짝 입힌 {buff}."
L["Here, {name}. Hand-cast in Silvermoon, so do try not to scuff it."] = "여기요, {name}. 실버문 수제 주문이니까 흠집 내지 않게 조심해요."
L["The Sunwell shines for us both, {name}."] = "태양샘은 우리 둘 모두를 비추지요, {name}."
L["Two sin'dorei in one place, {name}. The day just got twice as elegant."] = "신도레이가 둘이라니, {name}. 오늘 하루가 두 배로 우아해졌네요."
L["You too, {name}? Two sin'dorei, one mirror. We'll have to take turns."] = "그대도요, {name}? 신도레이 둘에 거울은 하나. 번갈아 써야겠네요."
L["Like the phoenix, {name}: we keep rising, and we look good doing it."] = "불사조처럼요, {name}. 우린 계속 되살아나죠. 그것도 멋지게."
L["Do keep pace, {name}. We have a reputation for arriving beautifully."] = "보조 좀 맞춰 줘요, {name}. 우린 도착도 아름답게 하기로 유명하니까."
L["Stand where the light is good, {name}. If we must fight, we'll look splendid."] = "조명 좋은 데 서요, {name}. 싸워야 한다면 근사해 보여야죠."
L["A party at last, {name}. I did dress for one."] = "드디어 파티네요, {name}. 파티 옷차림으로 왔거든요."
L["The sun shines on all of us, {name}. Mostly on me, but it shares."] = "태양은 우리 모두를 비춰요, {name}. 주로 나를 비추지만, 나눠 주긴 하죠."
L["One for you, {name}, and one for the party's image, which I've taken on myself."] = "하나는 그대에게, {name}. 하나는 파티 이미지를 위해서. 그건 내가 맡았어요."
L["The sun has risen, {name}, and so have I. We coordinate."] = "해가 떴어요, {name}. 나도 일어났죠. 우린 맞춰 움직이거든요."
L["Dawn over Quel'Thalas is lovelier, {name}, but this will do. Just."] = "쿠엘탈라스의 새벽만은 못해도, {name}, 봐줄 만하네요. 겨우."
L["Morning light, {name}. The most flattering hour. For both of us, naturally."] = "아침 햇살이네요, {name}. 가장 잘 나오는 시간이죠. 물론 우리 둘 다."
L["Your generosity is noted, {name}. In triplicate. Suramar remembers its friends."] = "그 아량, 기록해 두죠, {name}. 세 부로. 수라마르는 벗을 잊지 않으니."
L["Most gracious, {name}. Allow me to repay you in kind."] = "참으로 고상하시군요, {name}. 같은 것으로 보답하지요."
L["Thank you, {name}. Ten thousand years under a dome; I'm still practising that."] = "고마워요, {name}. 만 년을 보호막 아래 살아서, 이 말은 아직 연습 중이에요."
L["A gift with no favour owed? The court would faint. Thank you, {name}."] = "대가 없는 선물이라니요? 궁정이 기절하겠군요. 고마워요, {name}."
L["Returned, {name}. We keep careful accounts of kindness. And of slights."] = "갚았어요, {name}. 우린 친절을 꼼꼼히 장부에 적거든요. 모욕도요."
L["I'll mention you to First Arcanist Thalyssra, {name}. Favourably, even."] = "탈리스라 님께 그대 얘기를 하죠, {name}. 좋게 말이에요."
L["Most kind, {name}. In Suramar we'd hold a banquet. Consider it held."] = "친절하시군요, {name}. 수라마르라면 연회를 열었겠죠. 연 걸로 치세요."
L["I'd send a formal letter of thanks, {name}, but this seemed quicker."] = "정식 감사 서한을 보내려 했지만, {name}, 이게 더 빠르겠더군요."
L["Of course, {name}. A little arcane polish, just for you."] = "물론이죠, {name}. 그대만을 위한 비전의 광택을 살짝."
L["A reasonable request, {name}. Granted."] = "합당한 요청이군요, {name}. 들어드리죠."
L["Certainly, {name}. The short version; the long one takes a lunar cycle."] = "그러죠, {name}. 짧은 버전으로요. 긴 버전은 한 달이 걸리거든요."
L["A request, how refreshing. The court only ever made demands. Here, {name}."] = "부탁이라니, 신선하군요. 궁정은 요구만 했거든요. 여기요, {name}."
L["Done, {name}, and free. Elisande would have charged you a favour for it."] = "됐어요, {name}. 공짜로요. 엘리산드였다면 대가를 요구했을 거예요."
L["There, {name}. No need to bow. A small nod would be lovely, though."] = "됐어요, {name}. 절할 필요는 없어요. 가볍게 고개만 끄덕여 주면 좋겠지만."
L["Of course, {name}. I've perfected this since before most cities had walls."] = "물론이죠, {name}. 대부분의 도시에 성벽도 없던 시절부터 갈고닦았거든요."
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "받으세요, {name}. 비전의 선물은 게으른 자에겐 낭비니까요."
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "수라마르 비전의 불꽃 한 점이에요, {name}. 현명하게 쓰시길."
L["I've gone without magic once, {name}. I don't recommend it. Take this."] = "마법 없이 지내 본 적이 있어요, {name}. 추천은 안 해요. 받으세요."
L["The world outside the dome is so large, {name}. And so under-enchanted. Here."] = "보호막 밖 세상은 참 넓네요, {name}. 마법은 너무 부족하고. 여기요."
L["Arcwine is traditional, {name}, but {buff} travels better."] = "비전술이 전통이지만, {name}, 들고 다니기엔 {buff} 쪽이 낫죠."
L["Do take this, {name}. It's rude to refuse Suramar's hospitality. Very rude."] = "받으세요, {name}. 수라마르의 환대를 거절하는 건 무례해요. 아주 무례하죠."
L["Here, {name}. I'm told this is how outsiders say hello. Charming custom."] = "여기요, {name}. 바깥에선 이렇게 인사한다더군요. 매력적인 풍습이에요."
L["Take this, {name}. Magic hoarded is magic spoiled, as Suramar learned."] = "받으세요, {name}. 쌓아 둔 마법은 썩는 법이죠. 수라마르가 배웠듯이."
L["Suramar's children shine together again, {name}."] = "수라마르의 자손들이 다시 함께 빛나는군요, {name}."
L["Shal'dorei, {name}! You packed arcwine? Outsider wine is just... grapes."] = "샬도레이군요, {name}! 비전술 챙겼어요? 바깥 술은 그냥... 포도예요."
L["Suramar's own, {name}. Try not to be too impressed by the rest of the world."] = "수라마르 사람이군요, {name}. 바깥세상에 너무 감탄하지는 말아요."
L["We survived the Legion and the withering, {name}. The rest is small talk."] = "군단도 메마름도 버텨 냈죠, {name}. 나머진 잡담거리예요."
L["An expedition, {name}! In Suramar this needed six permits and a masquerade."] = "원정이군요, {name}! 수라마르라면 허가증 여섯 장에 가면무도회까지 필요했죠."
L["The dome kept us safe, {name}. Now we must make do with one another. Gladly."] = "보호막이 우릴 지켜 줬죠, {name}. 이젠 서로가 지켜야죠. 기꺼이."
L["Arcane for everyone, {name}. The court would call it waste. I call it company."] = "모두에게 비전 마법을, {name}. 궁정은 낭비라 하겠지만, 난 동료애라 부르죠."
L["Do follow my lead, {name}. I've had ten thousand years of walking in step."] = "나를 따라와요, {name}. 만 년 동안 발맞춰 걷는 연습을 했거든요."
L["In a party one shares one's magic, {name}. How novel. I rather like it."] = "파티에선 마법을 나누는군요, {name}. 참 새롭네요. 꽤 마음에 들어요."
L["Night at last, {name}. Add a few thousand lanterns and it's nearly Suramar."] = "드디어 밤이네요, {name}. 등불 몇천 개만 달면 거의 수라마르예요."
L["Under the dome it was always night, {name}. I feel quite at home."] = "보호막 아래선 늘 밤이었죠, {name}. 집에 온 기분이에요."
L["The stars are out, {name}. We had better ones in Suramar. These will do."] = "별이 떴네요, {name}. 수라마르 별이 더 예뻤지만, 이 정도면 됐어요."
L["Daylight, {name}. Ten thousand years under a dome, and it still startles me."] = "햇빛이네요, {name}. 만 년을 보호막 아래 살아서, 아직도 깜짝 놀라요."
L["An early hour, {name}. The court never rose before noon. I'm reforming."] = "이른 아침이네요, {name}. 궁정은 정오까지 잤죠. 전 개과천선 중이에요."
L["Morning, {name}. The sun here is so very... unenchanted. Take this instead."] = "좋은 아침이에요, {name}. 여기 태양은 참... 마법이 없네요. 대신 이걸 받으세요."
L["A favour for a favour, {name}! Pleasure doing business."] = "호의엔 호의로, {name}! 거래 즐거웠다고!"
L["Thanks, {name}! Consider your account settled in full."] = "고마워, {name}! 이걸로 계산 끝, 완납이야!"
L["Aw, {name}. I'd invoice you, but I'm feeling sentimental. It'll pass."] = "아이고, {name}. 청구서 쓰려다 감성에 젖어서 참는다. 금방 깰 거야."
L["Thanks, {name}! I checked it for fine print. There wasn't any. Weird!"] = "고마워, {name}! 깨알 같은 약관 찾아봤는데 없더라. 이상하네!"
L["Returned with interest, {name}. Minus the interest. Don't get used to it."] = "이자까지 쳐서 갚는다, {name}. 이자는 빼고. 익숙해지진 마."
L["Much obliged, {name}! You've just been upgraded to preferred customer."] = "고마워, {name}! 방금 VIP 고객으로 승급됐어."
L["I'd name a rocket after you, {name}, but my rockets never last long. Thanks!"] = "네 이름 딴 로켓을 만들고 싶은데, {name}, 내 로켓은 오래 못 가서. 고마워!"
L["I'd have charged fifty gold for that, {name}. Let's call us even."] = "원래 50골드 받는 건데, {name}. 퉁치자고."
L["You got it, {name}! Time is money, friend!"] = "알았어, {name}! 시간은 금이라고, 친구!"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "거래 성사, {name}! 외상으로 달아 둘게. 농담이야!"
L["Right away, {name}! Satisfaction guaranteed or your {buff} back."] = "바로 간다, {name}! 불만족 시 {buff} 전액 환불!"
L["{buff}, {name}! Tips optional. Encouraged. Optional."] = "{buff} 나왔다, {name}! 팁은 선택. 권장. 선택."
L["Fast, cheap or good, {name}? Today you get all three. Don't spread it around."] = "빠르게, 싸게, 좋게 중 하나? {name}, 오늘은 셋 다야. 소문내지 마."
L["Sure thing, {name}! No explosions this time, I promise. Mostly promise."] = "물론이지, {name}! 이번엔 폭발 없어, 약속해. 거의 약속해."
L["For you, {name}? No charge. Put that in writing and I'll deny it."] = "너한텐 공짜야, {name}. 문서로 남기면 발뺌할 거지만."
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "이건 서비스야, {name}. 무역왕한텐 비밀이다?"
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "최고급 상품, 수수료 없음, {name}. 오늘만이야!"
L["Free sample, {name}! If you like it, you know where to find me."] = "무료 샘플이야, {name}! 마음에 들면 어디로 오면 되는지 알지?"
L["Here, {name}. If anything explodes near you today, that was unrelated."] = "자, {name}. 오늘 근처에서 뭐가 터지면, 이거랑은 무관한 거다."
L["Goodwill's an asset, {name}. Here's some {buff} for my books."] = "호감도 자산이지, {name}. 장부 채우는 셈 치고 {buff} 받아."
L["Take this, {name}. Safety first! Or third. It's on the list somewhere."] = "받아, {name}. 안전 제일! 아니, 제삼인가. 목록 어딘가엔 있어."
L["Cast in record time, {name}! The record's mine. I set it just now."] = "신기록으로 시전 완료, {name}! 기록 보유자는 나. 방금 세웠어."
L["Kaja'Cola gives you ideas, {name}. This does the rest. Take it!"] = "카자콜라는 아이디어를 주지, {name}. 나머진 이게 해 줘. 받아!"
L["Anything for a fellow entrepreneur, {name}!"] = "동료 사업가를 위해서라면 뭐든지, {name}!"
L["Kezan's finest, together again, {name}. Keep a hand on your coin purse."] = "케잔의 인재들이 다시 뭉쳤네, {name}. 지갑은 꽉 쥐고 있어."
L["Fellow goblin, {name}? Then you know this is a very, very rare discount."] = "고블린이야, {name}? 그럼 이게 아주아주 드문 할인인 거 알지?"
L["Goblins look after goblins, {name}. It's cheaper than hiring guards."] = "고블린은 고블린끼리 챙겨, {name}. 경비 고용하는 것보다 싸거든."
L["Group rate, {name}! Everybody here gets it half off. Of free."] = "단체 할인이야, {name}! 전원 반값. 공짜의 반값."
L["Nobody dies on my contract, {name}. The paperwork's a nightmare."] = "내 계약 기간엔 아무도 못 죽어, {name}. 서류 작업이 지옥이거든."
L["We split the loot even, {name}. I'll do the maths. Trust me."] = "전리품은 공평하게 나누자, {name}. 계산은 내가 할게. 믿어."
L["Team-building, {name}! You make everybody stronger, and they all owe you."] = "팀 빌딩이야, {name}! 다들 세지고, 다들 너한테 빚지는 거지."
L["Stick together, {name}. Mercenaries cost gold; friends only cost this."] = "뭉쳐 다니자, {name}. 용병은 골드가 들지만, 친구는 이거면 돼."
L["Early bird gets the gold, {name}! Here's a freebie. Don't tell the other birds."] = "일찍 일어나는 새가 골드를 번다, {name}! 공짜 하나. 다른 새들한텐 비밀."
L["Morning, {name}! Markets open in an hour. Until then, I'm feeling generous."] = "좋은 아침, {name}! 한 시간 뒤 장 열린다. 그때까진 인심 좀 쓰지."
L["Up early, {name}? Smart. Time is money, and it's cheapest in the morning."] = "일찍 일어났네, {name}? 똑똑하군. 시간은 금인데, 아침이 제일 싸거든."
L["Thank you, {name}! The caravan always repays a kindness. Usually in string."] = "고마워요, {name}님! 대상단은 받은 친절을 꼭 갚아요. 주로 끈으로요."
L["How kind, {name}! You're on the caravan's good list now."] = "다정하셔라, {name}님! 대상단 좋은 친구 명단에 올렸어요."
L["Oh, I'll keep this, {name}! I keep everything. Here's one for you."] = "어머, 이건 간직할게요, {name}님! 전 뭐든 간직하거든요. 이건 드릴게요."
L["Thanks, {name}! Here's yours back. Well, a new one. Hardly used."] = "고마워요, {name}님! 돌려드릴게요. 아니, 새 거예요. 거의 안 썼어요."
L["My ears just went straight up, {name}. That means I'm very pleased."] = "방금 귀가 쫑긋 섰어요, {name}님. 아주 기쁘다는 뜻이에요."
L["By tonight's campfire, {name}, this story will have a sandworm in it. Thanks!"] = "오늘 밤 모닥불 앞에선, {name}님, 이 얘기에 모래벌레가 나올 거예요. 고마워요!"
L["I'd gift-wrap yours, {name}, but all my wrapping is somebody's old map."] = "포장해 드리고 싶은데, {name}님, 포장지가 전부 누군가의 옛 지도라서요."
L["The alpacas saw that, {name}. They'll tell everyone how nice you are. Thanks!"] = "알파카들이 봤어요, {name}님. 좋은 분이라고 여기저기 소문낼 거예요. 고마워요!"
L["Of course, {name}! Shake the sand out and hold still."] = "물론이죠, {name}님! 모래 좀 털고 가만히 있어요."
L["Coming right up, {name}! Caravan service, no waiting."] = "바로 갑니다, {name}님! 대상단 서비스, 대기 없음!"
L["Sure, {name}! Let me dig it out... rope, rocks, a nice rock... here it is!"] = "그럼요, {name}님! 잠깐 찾아볼게요... 밧줄, 돌, 예쁜 돌... 여기 있다!"
L["Hold on, {name}! Tail's in the way, one moment... there!"] = "잠깐만요, {name}님! 꼬리가 걸려서, 잠시만... 됐다!"
L["One {buff}, {name}! Only slightly sandy."] = "{buff} 하나요, {name}님! 모래가 살짝 묻었어요."
L["Ask a vulpera and you'll get something, {name}. Usually odd. Not today!"] = "불페라한테 부탁하면 뭐든 나와요, {name}님. 대개 이상한 게. 오늘은 빼고요!"
L["Yours, {name}! Vulpera love giving things. Almost as much as finding them."] = "받으세요, {name}님! 불페라는 주는 걸 좋아해요. 줍는 거 다음으로요."
L["Every traveller needs something for the road, {name}. I checked: not a rock."] = "나그네라면 길에서 쓸 게 필요하죠, {name}님. 확인했어요, 돌 아니에요."
L["Keep this, {name}. The desert is long and the water is short."] = "챙겨 가요, {name}님. 사막은 길고 물은 부족하니까."
L["Found this lying around, {name}. Kidding! It's fresh. Take it!"] = "길에서 주웠어요, {name}님. 농담이에요! 새 거예요. 받으세요!"
L["Here, {name}. Best thing in my pack, and I've got a lot of pack."] = "여기요, {name}님. 제 짐 중에 최고예요. 짐이 엄청 많은데도요."
L["In the dunes you share your shade and your spells, {name}. Here."] = "사막에선 그늘도 주문도 나누는 법이에요, {name}님. 여기요."
L["Some {buff} for you, {name}. I'd haggle, but you look busy."] = "{name}님, {buff} 드릴게요. 흥정하고 싶지만 바빠 보이셔서."
L["A gift from the whole caravan, {name}! They'll never know."] = "대상단 모두가 드리는 선물이에요, {name}님! 다들 모르겠지만요."
L["For the road, {name}. Roads are the best part. Roads, and snacks."] = "가는 길에 쓰세요, {name}님. 여행은 길이 최고예요. 길이랑 간식이요."
L["A fellow wanderer! The caravan is never far, {name}."] = "같은 방랑자네요! 대상단은 늘 가까이 있어요, {name}님."
L["Ears up, {name}! Always nice to share a spell with a fellow fox."] = "귀 쫑긋, {name}님! 같은 여우랑 주문 나누는 건 언제나 좋아요."
L["One vulpera to another, {name}: I've three spare spoons if you need one."] = "불페라끼리 말인데요, {name}님. 여분 숟가락 세 개 있어요. 하나 드려요?"
L["Vol'dun raised us both, {name}. Sand in the fur, luck in the pack."] = "우린 둘 다 볼던이 키웠죠, {name}님. 털엔 모래, 짐엔 행운."
L["Caravan rules, {name}: stay together, share the water, nobody sells the alpaca."] = "대상단 규칙이에요, {name}님. 함께 다니기, 물 나누기, 알파카 팔지 않기."
L["Anything shiny in there, {name}, I saw it first. Caravan law."] = "반짝이는 건, {name}님, 제가 먼저 봤어요. 대상단 법이에요."
L["One for the party, {name}! A caravan's only as fast as its slowest alpaca."] = "파티에 하나씩요, {name}님! 대상단은 제일 느린 알파카만큼만 빠르거든요."
L["Keep your pack shut, {name}. I don't mean to take things. They follow me."] = "가방 잘 닫으세요, {name}님. 제가 가져가는 게 아니라 물건이 절 따라와요."
L["Lost in a city, {name}, never in a cave. Caves are just houses with no rent."] = "도시에선 길을 잃어도 동굴에선 안 잃어요, {name}님. 월세 없는 집이거든요."
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids."] = "불페라는 밤에 다녀요, {name}님. 모래는 시원하고, 전갈은 졸리고."
L["Desert nights get cold, {name}. Here, something warm-ish."] = "사막의 밤은 추워요, {name}님. 여기, 따끈... 아니, 미지근한 거요."
L["Stars out, {name}. Every one's a signpost if you know how to read it. I don't."] = "별이 떴어요, {name}님. 읽을 줄 알면 전부 이정표래요. 전 못 읽어요."
L["A kindness returned is a kindness doubled, {name}."] = "돌려준 친절은 두 배가 되는 법이라네, {name}."
L["Thank you, {name}. You have restored my balance."] = "고맙네, {name}. 덕분에 내 균형이 돌아왔다네."
L["Somewhere, a Sha just went hungry. Thank you, {name}."] = "어딘가에서 샤 하나가 굶게 됐구먼. 고맙네, {name}."
L["Thank you, {name}. Aysa would bow, Ji would cheer. I will do both, badly."] = "고맙네, {name}. 아이사는 절을, 지는 환호를 했겠지. 난 둘 다 하겠네. 서툴게."
L["Thank you, {name}. I will think of you at my next meal, and the one after."] = "고맙네, {name}. 다음 끼니 때 자넬 생각하겠네. 그다음 끼니 때도."
L["Chen always said: never refuse a gift. Or a drink. Thank you, {name}."] = "첸이 늘 말했지. 선물은 거절 말라고. 술도. 고맙네, {name}."
L["I was about to nap, {name}, but this is better. Slightly. Thank you."] = "막 낮잠 자려던 참이었네, {name}. 그런데 이게 더 좋군. 조금. 고맙네."
L["A hozen would have thrown something, {name}. I was raised better. Thank you."] = "호젠이었다면 뭘 던졌을 걸세, {name}. 난 제대로 배웠지. 고맙네."
L["Of course, {name}. Patience, and it is done. Patience is the slow part."] = "물론이지, {name}. 조금만 참으면 다 된다네. 참는 게 느려서 그렇지."
L["With pleasure, {name}. A kind deed is never wasted."] = "기꺼이 하지, {name}. 선행은 결코 헛되지 않다네."
L["At once, {name}. Quick for a pandaren, which is not saying much."] = "당장 하지, {name}. 판다렌치고는 빠르게. 그래 봐야 별거 아니지만."
L["Master Shang Xi said: help whoever asks, {name}. He also said: duck."] = "샹 시 사부께선 청하면 도우라 하셨네, {name}. '숙여!'라고도 하셨고."
L["A Tushui master would make you meditate first, {name}. I will skip that part."] = "투슈이 사부라면 명상부터 시켰을 걸세, {name}. 그건 건너뛰세."
L["Anything for you, {name}. Except the last dumpling. Let us not be silly."] = "자네를 위해서라면 뭐든지, {name}. 마지막 만두만 빼고. 실없는 소린 말게."
L["One {buff}, {name}, brewed strong. The recipe stays a secret."] = "{buff} 한 잔, 진하게 우렸네, {name}. 비법은 비밀일세."
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "받게, {name}. 그리고 끝나면 차 한잔 어떤가?"
L["Balance in all things, {name}. Now go with a light heart."] = "모든 일엔 균형이라네, {name}. 이제 가벼운 마음으로 가게."
L["Take this, {name}. A grummle would sell it to you for a luckydo."] = "받게, {name}. 그러믈이었으면 행운 부적 받고 팔았을 걸세."
L["The jinyu say the waters foretold this, {name}. They say that a lot."] = "진유는 물이 이걸 예언했다 하더군, {name}. 늘 그 소리지만."
L["The Huojin say act first. The Tushui say think first. I say: here, {name}."] = "후오진은 행동 먼저, 투슈이는 생각 먼저. 난 이것 먼저일세. 받게, {name}."
L["A pandaren stood up to give you this, {name}. Treasure it."] = "판다렌이 일어나서까지 주는 걸세, {name}. 소중히 여기게."
L["Fight like a monk, {name}: calm, quick, and then a long lunch."] = "수도사처럼 싸우게, {name}. 차분히, 재빨리, 그리고 긴 점심."
L["Go gently, {name}. The turtle got where it was going and never hurried once."] = "천천히 가게, {name}. 거북이는 한 번도 안 서둘렀어도 갈 곳에 닿았다네."
L["We must share a brew when the road allows, {name}!"] = "길이 허락하면 술 한잔 나누세, {name}!"
L["Shen-zin Su would be proud of us both, {name}. Or asleep. Hard to tell."] = "셴진 수도 흐뭇해할 걸세, {name}. 아니면 자는 중이거나. 구분이 안 가지."
L["Two pandaren together, {name}. Somewhere, an innkeeper just felt a chill."] = "판다렌이 둘이나 모였군, {name}. 어디선가 여관 주인이 오싹했을 걸세."
L["Liu Lang would approve, {name}: two of us, both a long way from home."] = "리우 랑도 좋아하겠군, {name}. 우리 둘 다 고향에서 멀리 왔으니."
L["A fight, then a meal, {name}. That is the correct order. Never the reverse."] = "싸움 다음에 밥일세, {name}. 그게 올바른 순서지. 절대 반대로는 안 되네."
L["Stay together, {name}, like dumplings in a steamer. Warm, and ready."] = "찜기 속 만두처럼 붙어 있게, {name}. 따끈하게, 준비된 채로."
L["We move as one, {name}. Slowly, perhaps, but as one."] = "우린 한 몸처럼 움직이네, {name}. 좀 느릴지언정, 한 몸처럼."
L["Balance, {name}: one fights, one heals, and one carries the snacks. Me."] = "균형일세, {name}. 하나는 싸우고, 하나는 치유하고, 하나는 간식을 들지. 나."
L["If we fall, {name}, we fall together, and then we nap. Let us not."] = "쓰러지면, {name}, 다 같이 쓰러져서 낮잠이나 자세. 아니, 그러지 마세."
L["Up before the tea, {name}? Brave. Here, instead of the tea."] = "차보다 먼저 일어났나, {name}? 용감하군. 자, 차 대신 이걸 받게."
L["Morning, {name}. First this, then breakfast, then the second breakfast."] = "좋은 아침일세, {name}. 먼저 이거, 그다음 아침, 그다음 두 번째 아침."
L["A new day, {name}, and nobody has spilled anything yet. Let us begin gently."] = "새날이 밝았네, {name}. 아직 아무도 뭘 쏟지 않았군. 살살 시작하세."
L["Past my first nap, {name}, and before my second. Quickly, while I'm awake."] = "첫 낮잠은 지났고 두 번째 낮잠 전일세, {name}. 깨어 있을 때 얼른."
L["Late, {name}. The brewmasters are asleep. The brews, I suspect, are not."] = "밤이 깊었네, {name}. 양조사들은 잠들었지. 술은 아직 안 자는 것 같네만."
L["Midnight snack time, {name}. This is the appetiser."] = "야식 시간일세, {name}. 이건 전채 요리고."
L["Your kindness is noted, {name}. Dragons do not forget."] = "그대의 친절, 새겨 두겠소, {name}. 용은 잊지 않소."
L["Thank you, {name}. Returned on swift wings."] = "고맙구려, {name}. 날랜 날갯짓으로 갚겠소."
L["Wings, fire and scales, {name}, and still you thought I needed help. Touching."] = "날개도 불도 비늘도 있는데, {name}, 그래도 도와주다니. 감동이구려."
L["I would bow, {name}, but last time my wings cleared a table. Thank you."] = "절이라도 하고 싶소, {name}. 지난번엔 날개로 식탁을 쓸어 버렸지만. 고맙소."
L["That goes straight into my hoard, {name}. Kind deeds are the only gold I keep."] = "곧장 내 보물 더미에 넣겠소, {name}. 내가 모으는 금은 선행뿐이오."
L["I was made to be a weapon, {name}. I much prefer this part. Thank you."] = "난 무기로 만들어졌소, {name}. 이쪽이 훨씬 마음에 드오. 고맙소."
L["Thank you, {name}. Wrathion would have made a speech of it. I will not."] = "고맙소, {name}. 래시온이었다면 연설을 했을 거요. 난 안 하겠소."
L["Returned with a little fire in it, {name}. Only a little. I am practising."] = "불기를 살짝 담아 돌려드리오, {name}. 아주 살짝. 연습 중이라."
L["Very well, {name}. Stand still, I would hate to singe you."] = "알겠소, {name}. 가만히 계시오. 그을리게 하고 싶진 않으니."
L["Granted, {name}. A dragon keeps its word."] = "들어주겠소, {name}. 용은 약속을 지키는 법."
L["Certainly, {name}. Stand clear of the tail."] = "그러겠소, {name}. 꼬리에서 떨어져 계시오."
L["Of course, {name}. Is this still how it is done? I was asleep for a while."] = "물론이오, {name}. 요즘도 이렇게 하는 거요? 잠깐 눈 좀 붙였더니만."
L["Gladly, {name}. All five dragonflights are in me, and all five say yes."] = "기꺼이, {name}. 내 안의 다섯 용군단이 만장일치로 찬성이오."
L["Right away, {name}. Dragon-sized help, in a conveniently smaller form."] = "당장 하리다, {name}. 용만 한 도움을, 들고 다니기 좋은 크기로."
L["Of course, {name}. Neltharion only gave orders. A request is much nicer."] = "물론이오, {name}. 넬타리온은 명령만 했지. 부탁이 훨씬 낫구려."
L["Take this, {name}. Even a dragon needs allies. Especially one this size."] = "이걸 받으시오, {name}. 용에게도 동료는 필요하오. 이리 아담한 용이면 더더욱."
L["A gift from the Dragon Isles, {name}. Fly well."] = "용의 섬에서 온 선물이오, {name}. 멋지게 날기를."
L["Alexstrasza says every life is precious, {name}. I am starting with yours."] = "알렉스트라자께선 모든 생명이 소중하다 하셨소, {name}. 그대부터 시작하리다."
L["I slept through ten thousand years of good deeds, {name}. Catching up now."] = "만 년 치 선행을 자느라 놓쳤소, {name}. 지금 몰아서 하는 중이오."
L["Tell them a dragon did this, {name}. It sounds far grander than it was."] = "용이 해 줬다고 전하시오, {name}. 실제보다 훨씬 그럴싸하게 들리니."
L["Scalecommander's orders, {name}. I am not a Scalecommander, but still."] = "비늘사령관의 명령이오, {name}. 내가 비늘사령관은 아니지만, 아무튼."
L["Take this, {name}. Ancient dragon magic, only slightly out of date."] = "받으시오, {name}. 고대 용의 마법이오. 유통기한이 살짝 지났지만."
L["A dragon giving, {name}, not taking. I am trying something new."] = "용이 빼앗지 않고 베푸는 거요, {name}. 새로운 시도랄까."
L["The Forbidden Reach feels far behind us now, {name}."] = "이제 금지된 해안도 먼 옛일 같구려, {name}."
L["Two dracthyr in one place, {name}. Mind the wings; there is not room for four."] = "드랙티르 둘이 한자리라니, {name}. 날개 조심하시오. 날개 넷 펼 자리는 없소."
L["Remember when the whole world was new to us, {name}? It still is, mostly."] = "세상 모든 게 낯설던 때 기억하오, {name}? 사실 아직도 대부분 낯설지만."
L["In visage form nobody can tell, {name}. Between us: we look better in scales."] = "사람 모습일 땐 아무도 모르지, {name}. 우리끼리 얘긴데, 비늘이 더 멋지오."
L["Tell me when to breathe fire, {name}. And, please, when not to."] = "불 뿜을 때가 되면 말해 주시오, {name}. 뿜지 말아야 할 때도 꼭."
L["I woke in a cave full of strangers, {name}. This is far better company."] = "눈 떠 보니 낯선 이들 가득한 동굴이었소, {name}. 여기가 훨씬 낫구려."
L["Neltharion made us to fight alone, {name}. We have improved on him."] = "넬타리온은 우릴 홀로 싸우도록 빚었소, {name}. 설계는 우리가 고쳤지."
L["Stay clear of my tail, {name}. It hasn't yet learned whose side it's on."] = "내 꼬리는 피하시오, {name}. 아직 누구 편인지 모르는 녀석이라."
L["A flight of our own, {name}. So this is what the dragons meant."] = "우리만의 용군단이오, {name}. 용들이 말하던 게 이런 거였구려."
L["It is good to see one of our own, {name}."] = "동족을 만나니 반갑구려, {name}."
L["Our people are few, {name}. That makes each of us count."] = "우리 동족은 수가 적소, {name}. 그래서 하나하나가 소중하오."
L["Thank you, {name}. The Alliance looks after its own, and today that's me."] = "고맙소, {name}. 얼라이언스는 동료를 챙기는 법이오. 오늘은 나였구려."
L["Kindness answered, {name}. For the Alliance!"] = "호의에 보답하오, {name}. 얼라이언스를 위하여!"
L["Stormwind has a statue for every hero, {name}. I'm putting in a word for yours."] = "스톰윈드엔 영웅마다 동상이 있소, {name}. 그대 동상도 건의해 두겠소."
L["The Alliance way, {name}: you help me, I help you, a dwarf buys the drinks."] = "얼라이언스 방식이오, {name}. 그대가 돕고, 내가 돕고, 술은 드워프가 사고."
L["Genn would growl, Muradin would hug, {name}. I'll just return it."] = "겐이라면 으르렁, 무라딘이라면 와락. 난 그냥 갚겠소, {name}."
L["If the Alliance gave medals for manners, {name}, you'd need a second tabard."] = "얼라이언스가 예의 훈장을 준다면, {name}, 휘장이 하나 더 필요하겠구려."
L["Returned in full, {name}. An ally who gives first is worth a whole garrison."] = "고스란히 갚았소, {name}. 먼저 베푸는 동료는 수비대 하나와 맞먹소."
L["Of course, {name}. Allies help each other. It's practically in the name."] = "당연하오, {name}. 동맹은 서로 돕는 법. 이름부터 얼라이언스 아니오."
L["At once, {name}. The Alliance does not leave a friend wanting."] = "곧바로 하겠소, {name}. 얼라이언스는 벗을 외면하지 않소."
L["Of course, {name}. It's in the Alliance charter. Somewhere near the back."] = "물론이오, {name}. 얼라이언스 헌장에 있는 조항이오. 한참 뒤쪽 어딘가에."
L["By order of the Alliance, {name}: one {buff}, effective at once."] = "얼라이언스 명령이오, {name}. {buff} 1건, 즉시 발효."
L["Anything for an ally, {name}. Within reason. This is well within reason."] = "동맹을 위해선 뭐든 하오, {name}. 상식선에서. 이건 충분히 상식선이오."
L["Right away, {name}. SI:7 knew you would ask. I only just found out."] = "당장 하겠소, {name}. SI:7은 그대가 부탁할 줄 알았다더군. 난 방금 알았소."
L["For the Alliance, {name}! Stay strong out there. Stronger, now."] = "얼라이언스를 위하여, {name}! 굳건히 버티시오. 이제 더 굳건히."
L["Onward, {name}. The Alliance is with you."] = "전진하시오, {name}. 얼라이언스가 함께하오."
L["Take this, {name}. Had a gnome made it, it would come with twelve levers."] = "받으시오, {name}. 노움이 만들었다면 레버가 열두 개는 달렸을 거요."
L["Compliments of the Alliance, {name}. We've done these since the Second War."] = "얼라이언스가 드리는 거요, {name}. 2차 대전쟁 때부터 해 온 일이지."
L["Chin up, {name}. Somewhere in Stormwind, a bard is writing about this."] = "고개 드시오, {name}. 스톰윈드 어딘가서 음유시인이 이 얘길 쓰는 중이오."
L["Every ally counts, {name}. I counted, actually. You're my favourite so far."] = "동료 하나하나가 소중하오, {name}. 세어 봤는데, 아직까진 그대가 최고요."
L["Anduin would want me to share, {name}, and I'd hate to disappoint him."] = "안두인이라면 나누라 했을 거요, {name}. 그분을 실망시킬 순 없지."
L["Together we stand, {name}. For the Alliance!"] = "뭉쳐야 사는 법이오, {name}. 얼라이언스를 위하여!"
L["Right, {name}: shields up, heads down, and nobody charges before the plan does."] = "자, {name}. 방패는 들고, 고개는 숙이고, 작전보다 먼저 돌격하는 자 없기요."
L["The finest company the Alliance ever fielded, {name}. Or at least the nearest."] = "얼라이언스 역사상 최고의 부대요, {name}. 적어도 제일 가까이 있는 부대."
L["Together, {name}, we're practically a regiment. A small, well-dressed regiment."] = "모이니 거의 연대 규모요, {name}. 작지만 옷 잘 입은 연대."
L["Watch each other's backs, {name}. The Alliance was built by people who did."] = "서로 등을 지켜 주시오, {name}. 얼라이언스는 그런 이들이 세운 거요."
L["Strength and honour, {name}. And kindness, it turns out. Repaid in full."] = "힘과 명예, {name}. 알고 보니 친절도 있구려. 고스란히 갚았소."
L["The Horde takes care of its own, {name}."] = "호드는 제 식구를 챙기는 법이오, {name}."
L["Strength given, strength returned, {name}. That's all of Horde diplomacy."] = "힘을 받았으면 힘으로 갚소, {name}. 호드 외교는 그게 전부요."
L["I'd carve your name on Orgrimmar's gates, {name}, but they're full. Thanks."] = "오그리마 성문에 그대 이름을 새기고 싶지만, {name}, 빈자리가 없소. 고맙소."
L["Gallywix would've sent you an invoice, {name}. I'm sending this instead."] = "갤리윅스였다면 청구서를 보냈을 거요, {name}. 난 대신 이걸 보내오."
L["You did not have to do that, {name}. That is why the Horde remembers it."] = "안 해도 될 일이었소, {name}. 그래서 호드는 이걸 기억하오."
L["In the Horde we do not say thank you twice, {name}. So: once, and meant."] = "호드는 고맙단 말을 두 번 하지 않소, {name}. 그러니 한 번, 진심으로."
L["Consider it done, {name}. For the Horde, and for anyone who asks nicely."] = "맡겨 두시오, {name}. 호드를 위하여, 그리고 예의 바른 모두를 위하여."
L["You only had to ask, {name}. The Horde answers."] = "말만 하면 되오, {name}. 호드는 응답하오."
L["The Horde usually helps with axes, {name}. Today, {buff}."] = "호드는 보통 도끼로 돕소, {name}. 오늘은 도끼 대신 {buff}."
L["Done, {name}. No speeches. The Horde has plenty of those already."] = "됐소, {name}. 연설은 생략하오. 호드엔 이미 차고 넘치니."
L["You asked, {name}. In Orgrimmar, that counts as a formal treaty."] = "청했으니 됐소, {name}. 오그리마에선 그게 정식 조약이오."
L["Asking is no weakness, {name}. Refusing an ally would be."] = "청하는 건 약함이 아니오, {name}. 동료를 거절하는 게 약함이지."
L["For the Horde, {name}! Go with strength. I've just handed you some."] = "호드를 위하여, {name}! 힘이 함께하기를. 방금 좀 넣어 드렸소."
L["Go with honour, {name}. Victory awaits."] = "명예롭게 가시오, {name}. 승리가 기다리오."
L["Go and do something worth a song, {name}. Loud songs. The Horde likes loud."] = "노래가 될 일을 하시오, {name}. 시끄러운 노래로. 호드는 시끄러운 게 좋소."
L["Walk tall, {name}. The Horde always made room for those the world turned away."] = "당당히 걸으시오, {name}. 호드는 늘 세상이 외면한 이들을 품었소."
L["Take this, {name}, and a word of Horde wisdom: hit first, apologise never."] = "받으시오, {name}. 호드의 지혜도 하나. 먼저 치고, 사과는 하지 마시오."
L["Victory or death, {name}. I'd prefer victory, so take this."] = "승리 아니면 죽음이오, {name}. 난 승리가 좋으니, 이걸 받으시오."
L["Like a mak'gora, {name}, except everybody wins. Here."] = "막고라 같은 거요, {name}. 다만 모두가 이기지. 받으시오."
L["Our strength is each other, {name}. For the Horde!"] = "우리의 힘은 서로에게 있소, {name}. 호드를 위하여!"
L["Forward, {name}. The Horde advances together. Retreats... never, officially."] = "전진하시오, {name}. 호드는 함께 전진하오. 후퇴는... 공식적으론 없소."
L["Together we're a war band, {name}. Apart, we're just loud."] = "뭉치면 전투부대요, {name}. 흩어지면 그냥 시끄러운 무리고."
L["Shoulder to shoulder, {name}. Whoever charges first buys the grog."] = "어깨를 나란히, {name}. 먼저 돌격하는 자가 술을 사는 거요."
L["Nobody gets left behind, {name}. I've counted us twice."] = "낙오자는 없소, {name}. 두 번이나 세어 봤소."
L["Thank you, {name}. Good hearts turn up on every side, and apparently here."] = "고맙소, {name}. 선한 마음은 어느 편에나 있다더니, 여기도 있구려."
L["Thank you, {name}. No side, no title, just kindness. Legends start like this."] = "고맙소, {name}. 편도 직함도 없이 친절 하나. 전설은 이렇게 시작하오."
L["Thank you, {name}. Kindness has no faction, which is handy, since I have none."] = "고맙소, {name}. 친절엔 진영이 없소. 마침 나도 없으니 잘됐구려."
L["Thank you, {name}. Whichever side gets you is getting a bargain."] = "고맙소, {name}. 어느 편이 그대를 데려가든 횡재하는 거요."
L["Whoever claims me in the end, {name}, I'll remember you first. Thank you."] = "결국 어느 편에 서든, {name}, 그대를 제일 먼저 기억하리다. 고맙소."
L["Strictly neutral, {name}, but gratitude doesn't count. Thank you."] = "철저히 중립이오, {name}. 하지만 감사는 예외지. 고맙소."
L["Gladly, {name}, whatever banner you fly. I don't even own a banner."] = "기꺼이, {name}. 그대가 어느 깃발 아래 있든. 난 깃발도 없지만."
L["Certainly, {name}. I help everyone. It's the one thing I've decided."] = "물론이오, {name}. 난 누구든 돕소. 그거 하나는 정했소."
L["Everyone asks me which side I'm on, {name}. Much nicer to be asked for help."] = "다들 어느 편이냐고만 묻더군, {name}. 도와 달란 말이 훨씬 반갑소."
L["Of course, {name}. No war council to ask; just me, and I say yes."] = "물론이오, {name}. 물어볼 전쟁 회의도 없소. 나 혼자고, 난 찬성이오."
L["Here you are, {name}. No oath, no colours, no fee."] = "여기 있소, {name}. 맹세도, 깃발도, 수수료도 없이."
L["Friends can come from any side, {name}. Or, like me, from none in particular."] = "벗은 어느 편에서든 오는 법이오, {name}. 나처럼 아무 편도 아닌 데서도."
L["Soon they'll hand us tabards, {name}. Until then, we look after each other."] = "곧 우리도 휘장을 받겠지, {name}. 그때까진 서로 챙깁시다."
L["I haven't chosen a side yet, {name}, so I'm being kind to both. Take this."] = "아직 편을 안 골랐소, {name}. 그래서 양쪽 다 잘해 주는 중이오. 받으시오."
L["A gift with no strings, {name}. I don't even have a faction to tie them to."] = "아무 조건 없는 선물이오, {name}. 조건 걸 진영도 없는 몸이라."
L["Go on, {name}. Two whole factions are waiting to argue over us."] = "어서 가시오, {name}. 두 진영이 우릴 두고 다툴 날만 기다리오."
L["No quartermaster yet, {name}, so nobody's counting. Have plenty."] = "아직 병참장교가 없어 아무도 안 세오, {name}. 넉넉히 받으시오."
L["Side by side, {name}, whatever comes."] = "어깨를 나란히, {name}. 무엇이 닥치든."
L["No flag over this party, {name}, just us. That's plenty."] = "이 파티엔 깃발 대신 우리가 있소, {name}. 그걸로 충분하오."
L["One day we'll pick sides, {name}. Today we pick fights, together."] = "편 가르기는 나중에, {name}. 오늘은 함께 적을 가릅시다."
L["Whatever side the rest of the world is on, {name}, I'm on this party's."] = "세상이 어느 편에 서든, {name}, 난 이 파티 편이오."
L["Neutral in the war, {name}, but very partial to this group."] = "전쟁에선 중립이오, {name}. 하지만 이 파티엔 대놓고 편파적이오."
L["One good turn deserves another, {name}."] = "은혜는 은혜로 갚는 법이오, {name}."
L["Have some {buff} in return, {name}."] = "답례로 {buff} 받으시오, {name}."
L["Kindness should go both ways, {name}. Thank you."] = "친절은 오가야 하는 법, {name}. 고맙소."
L["You went first, {name}, so I'll go second and we'll call it friendship."] = "그대가 먼저 했으니, {name}, 내가 이어받으면 그게 우정이오."
L["I'd write you a song, {name}, but {buff} is less off-key."] = "노래라도 지어 드리고 싶소만, {name}, {buff} 쪽이 음정은 덜 틀리오."
L["A gift for a gift, {name}. At this rate we'll be unstoppable by supper."] = "선물엔 선물로, {name}. 이 기세면 저녁때쯤엔 천하무적이겠소."
L["All square, {name}. Unless you'd like to make it best of three."] = "이걸로 비겼소, {name}. 삼세판으로 가자면 몰라도."
L["You started it, {name}. I'm only finishing it."] = "먼저 시작한 건 그대요, {name}. 난 마무리만 하는 거고."
L["That was kind, {name}. The day just got noticeably better. Here's my half."] = "고마운 일이오, {name}. 하루가 확 나아졌소. 이건 내 쪽 답례요."
L["You asked, {name}, and here it is."] = "청하신 대로요, {name}. 여기 있소."
L["{buff}, coming right up, {name}."] = "{name}, {buff} 바로 대령하오."
L["Gladly, {name}. One moment."] = "기꺼이 하리다, {name}. 잠시만 기다리시오."
L["Asked and answered, {name}. Next question?"] = "묻는 말에 답했소, {name}. 다음 질문?"
L["Say the word and it's yours, {name}. You said several. Here."] = "말 한마디면 그대 것이오, {name}. 몇 마디나 했으니, 여기."
L["For you, {name}? Gladly. I was hoping someone would ask."] = "그대를 위해서라면, {name}, 기꺼이. 누가 부탁하길 기다렸소."
L["Of course, {name}. Easiest yes I'll say all day."] = "물론이오, {name}. 오늘 이보다 쉬운 대답은 없을 거요."
L["Right away, {name}. Finally, a question I know the answer to."] = "바로 하리다, {name}. 드디어 답을 아는 질문이 나왔구려."
L["Safe travels, {name}. {buff} packs lighter than a sword."] = "무사히 가시오, {name}. {buff}만큼 가벼운 짐도 없소."
L["A small blessing for the road, {name}."] = "가는 길에 작은 축복을, {name}."
L["Go well, {name}, and come back in one piece."] = "잘 다녀오시오, {name}. 몸 성히 돌아오고."
L["No reason, {name}. It just felt like a {buff} sort of day."] = "이유는 없소, {name}. 그냥 {buff} 기분인 날이오."
L["Don't mind me, {name}. Just passing, with a spare {buff}."] = "신경 쓰지 마시오, {name}. 남는 {buff} 들고 지나가던 길이오."
L["Consider it a gift, {name}. I'd wrap it, but it glows through the paper."] = "선물이라 생각하시오, {name}. 포장하려 했는데 종이 너머로 빛이 새서."
L["Here, {name}. Pass it on when you meet someone who needs it."] = "여기, {name}. 필요한 이를 만나면 그대도 건네주시오."
L["Whatever brings you here, {name}, may it go better than planned."] = "무슨 일로 왔든, {name}, 계획보다 잘 풀리길 바라오."
L["Just being neighbourly, {name}. Very, very temporary neighbours."] = "이웃사촌끼리 정 나누는 거요, {name}. 아주아주 잠깐 이웃이지만."
L["Everyone ready? You are now, {name}."] = "모두 준비됐소? 이제 {name}도 준비됐소."
L["A little something for the party, {name}."] = "파티를 위한 작은 선물이오, {name}."
L["Stay close, {name}. We go further together."] = "가까이 붙어 있으시오, {name}. 함께라면 더 멀리 가오."
L["House rules, {name}: nobody dies, nobody sulks, everybody eats after."] = "우리 규칙이오, {name}. 죽지 말 것, 삐치지 말 것, 끝나면 다 같이 밥 먹을 것."
L["There, {name}. Now if this goes badly, it won't be my fault."] = "됐소, {name}. 이제 잘못돼도 내 탓은 아니오."
L["All set, {name}. I'd give a speech, but we'd be here all day."] = "준비 끝이오, {name}. 연설도 하고 싶지만 그러다 해 지겠소."
L["Look after that, {name}. It's the only one I brought for you."] = "잘 챙기시오, {name}. 그대 몫으로 가져온 건 그거 하나뿐이오."
L["Now we look the part, {name}. Let's go and be it."] = "이제 겉모습은 영웅이오, {name}. 가서 속까지 채웁시다."
L["Fresh {buff} all round, {name}. The rest is luck and elbows."] = "{buff}도 새로 돌렸소, {name}. 나머진 운과 팔꿈치 싸움이오."
L["Thank you, {name}. I'd conjure a gift in return, but it would only be water."] = "고맙소, {name}. 답례를 창조하려 해도 나오는 건 물빵뿐이라."
L["Much obliged, {name}. I'll write it up properly later. Several pages."] = "신세 졌소, {name}. 나중에 제대로 기록해 두겠소. 몇 장에 걸쳐."
L["Thank you, {name}. They never taught gratitude at Dalaran. I'm self-taught."] = "고맙소, {name}. 달라란에선 감사를 안 가르쳐서, 독학했소."
L["Kind of you, {name}. I'd say it went to my head, but that's my job."] = "고맙소, {name}. 콧대가 높아지겠구려. 원래 높아져야 할 건 지능인데."
L["Of course, {name}. And yes, I suppose you'll want water as well."] = "물론이오, {name}. 그리고 그래, 물도 달라는 거겠지."
L["As requested, {name}. Side effects may include footnotes."] = "요청하신 대로요, {name}. 부작용으로 각주가 생길 수 있소."
L["At once, {name}. Carefully, too; I've blinked into two walls today."] = "당장 하겠소, {name}. 조심해서. 오늘만 점멸로 벽에 두 번 박았소."
L["Gladly, {name}. Knowledge should be shared. The Kirin Tor say so, reluctantly."] = "기꺼이, {name}. 지식은 나눠야 하오. 키린 토도 그러더군. 마지못해."
L["Here, {name}. I had a spare thought and nowhere to put it."] = "여기, {name}. 생각이 하나 남는데 둘 데가 없어서."
L["Take this, {name}. I'd add bread, but conjured bread tastes of nothing."] = "받으시오, {name}. 빵도 얹고 싶지만, 마법으로 만든 빵은 아무 맛이 안 나오."
L["{buff} for you, {name}. No charge, unlike the portals."] = "{name}, {buff} 받으시오. 차원문과 달리 공짜요."
L["Here, {name}. Most folk I point at turn into sheep. Today's your lucky day."] = "여기, {name}. 내가 가리키면 대개 양이 되는데, 오늘은 운 좋은 날이오."
L["Nothing on fire, nothing frozen, {name}. I'm branching out."] = "아무것도 안 태우고 안 얼렸소, {name}. 새 분야를 개척 중이오."
L["Now that you're clever, {name}, stand between me and the angry things."] = "이제 똑똑해졌으니, {name}, 나와 화난 놈들 사이에 서 주시오."
L["For the record, {name}, I only blink away when it's tactically sound."] = "분명히 해 두겠소, {name}. 점멸로 빠지는 건 전술적 판단일 때뿐이오."
L["There, {name}. Wiser already: look, you're standing further from me."] = "됐소, {name}. 벌써 현명해졌군. 보시오, 나한테서 멀찍이 서 있잖소."
L["Minds sharpened, {name}. I'll handle the fire, the frost and the panicking."] = "머리는 맑아졌소, {name}. 화염, 냉기, 호들갑은 내가 맡지."
L["How thoughtful, {name}. The Light keeps accounts; I settle mine early."] = "사려 깊구려, {name}. 빛은 장부를 적으니, 난 미리 갚아 두리다."
L["Thank you, {name}. I'll put in a good word with the Light. It owes me several."] = "고맙소, {name}. 빛께 좋게 말해 두리다. 빛이 내게 빚이 좀 있거든."
L["Thank you, {name}. A small miracle, and I didn't even have to pray for it."] = "고맙소, {name}. 작은 기적이구려. 기도도 안 했는데."
L["Thank you, {name}. My faith in people is restored. It was only resting."] = "고맙소, {name}. 사람을 향한 믿음이 돌아왔소. 잠깐 쉬고 있었을 뿐이오."
L["Of course, {name}. The Light keeps no hours, and neither, sadly, do I."] = "물론이오, {name}. 빛엔 퇴근이 없소. 슬프게도 나도 없고."
L["Straight away, {name}. Most prayers take longer; you've found a shortcut."] = "바로 하리다, {name}. 기도는 보통 오래 걸리는데, 지름길을 찾았구려."
L["Certainly, {name}. The Light shines on those who ask. I just aim it."] = "물론이오, {name}. 빛은 구하는 이를 비추오. 난 조준만 할 뿐."
L["With pleasure, {name}. Faith moves mountains; I'm starting smaller."] = "기꺼이, {name}. 믿음은 산도 옮긴다지만, 난 작은 것부터 하겠소."
L["Bless you, {name}. No, you didn't sneeze; I'm simply thorough."] = "축복을, {name}. 재채기는 안 했소? 그럼 다음 재채기 몫으로 미리."
L["Here, {name}. Think of it as a prayer that arrived early."] = "여기, {name}. 일찍 도착한 기도라 생각하시오."
L["The Light asked me to pass this along, {name}. I'm paraphrasing."] = "빛께서 이걸 전하라 하셨소, {name}. 대충 그런 뜻이었소."
L["Take this, {name}. It saves us both an awkward resurrection later."] = "받으시오, {name}. 나중에 어색한 부활 장면을 서로 피할 수 있소."
L["Freely given, {name}. Faith costs nothing. The robes, sadly, did."] = "거저 드리오, {name}. 믿음은 공짜요. 이 로브는 아니었지만."
L["Your turn, {name}. Now, I beg you all: make my job boring."] = "그대 차례요, {name}. 다들 제발, 내 일을 지루하게 만들어 주시오."
L["Everyone stay near me, {name}. The Light has a limited range."] = "다들 내 곁에 있으시오, {name}. 빛도 사정거리가 있소."
L["There, {name}. If anyone falls, I'll be very disappointed, then fix it."] = "됐소, {name}. 누가 쓰러지면 몹시 실망할 거요. 그다음에 살리고."
L["Done, {name}. I'll be at the back, praying loudly."] = "끝났소, {name}. 난 맨 뒤에서 큰 소리로 기도하겠소."
L["Thank you, {name}. I'd purr, but I'm not in the right shape for it."] = "고맙소, {name}. 가르랑거리고 싶지만 지금은 그럴 모습이 아니라서."
L["Thanks, {name}. My bear form sends a grateful grunt."] = "고맙소, {name}. 곰 모습의 내가 고맙다고 '크릉' 하는구려."
L["Much obliged, {name}. My cat form wants to bring you a rabbit. I've said no."] = "신세 졌소, {name}. 표범 모습의 내가 토끼를 물어다 주겠다는 걸 말렸소."
L["Thank you, {name}. I'll plant a tree in your honour. Give it a century."] = "고맙소, {name}. 그대를 기려 나무를 심겠소. 백 년만 기다리시오."
L["Certainly, {name}. Give me a moment to remember which shape has hands."] = "물론이오, {name}. 어느 모습에 손이 있었는지 잠깐 떠올려 보고."
L["Of course, {name}. Hold still, like an oak. Oaks are wonderful at it."] = "물론이오, {name}. 참나무처럼 가만히. 참나무는 그걸 기막히게 잘하오."
L["Gladly, {name}. The wild shares everything. Well, not the bears."] = "기꺼이, {name}. 야생은 뭐든 나누오. 곰만 빼고."
L["Right away, {name}. Pardon the feathers; I've just come from being an owl."] = "바로 하리다, {name}. 깃털은 양해하시오. 방금까지 부엉이였소."
L["Fresh from the Emerald Dream, {name}. Sorry if I yawn."] = "에메랄드의 꿈에서 막 나온 거요, {name}. 하품하면 미안하오."
L["Take this, {name}. Nature provides, and I'm its errand runner today."] = "받으시오, {name}. 자연이 베푸는 거고, 오늘 난 심부름꾼이오."
L["The wild calls you friend now, {name}. Handy, since most of it has teeth."] = "이제 야생이 그대를 벗이라 부르오, {name}. 다행이오. 대개 이빨이 있으니."
L["I brought you flowers as well, {name}, but I was a stag at the time. Sorry."] = "꽃도 가져오려 했소, {name}. 사슴 모습이라 오다가 먹어 버렸지만."
L["Here, {name}. Cenarius would want you to have it. I'm nearly sure."] = "여기, {name}. 세나리우스께서도 그러길 바라셨을 거요. 아마 거의."
L["Ready, {name}? Now, whatever happens, nobody startle the bear."] = "준비됐소, {name}? 무슨 일이 있어도 곰은 놀래지 마시오."
L["There, {name}. I'll be the cat, the bear or, if we must swim, the seal."] = "됐소, {name}. 난 표범도, 곰도, 헤엄칠 일 생기면 바다표범도 되겠소."
L["I've one rebirth in me, {name}. Please, nobody make me choose."] = "환생은 한 번뿐이오, {name}. 제발 누굴 살릴지 고르게 하지 마시오."
L["Close ranks, {name}. The forest is watching, and it's rooting for us."] = "대열을 좁히시오, {name}. 숲이 지켜보고 있소. 뿌리 깊이 응원하면서."
L["Kindness, {name}? My favourite virtue. Just ahead of polishing."] = "친절이라, {name}? 내가 가장 아끼는 미덕이오. 갑옷 광내기를 근소하게 앞서지."
L["For that, {name}, my best blessing. Not the second best. The best."] = "그 보답으로, {name}, 최고의 축복을. 두 번째 말고, 최고로."
L["Virtue rewarded on the spot, {name}! I do love it when that happens."] = "선행이 즉석에서 보답받는구려, {name}! 이런 순간이 참 좋소."
L["Thank you, {name}. My oath says to repay kindness. I'd do it anyway."] = "고맙소, {name}. 내 맹세가 친절엔 보답하라 하오. 맹세 없어도 했겠지만."
L["By the Light, {name}, of course! I've been hoping somebody would ask."] = "빛의 이름으로, {name}, 물론이오! 누가 부탁하길 고대했소."
L["You have my blessing, {name}. Literally, this time."] = "내 축복을 받으시오, {name}. 이번엔 말 그대로."
L["Certainly, {name}. Kneel if you like. I won't insist. I'll be delighted."] = "물론이오, {name}. 원하면 무릎 꿇으시오. 강요는 않소. 기뻐는 하겠지만."
L["Gladly, {name}. I never run short of blessings. Mana, now and then."] = "기꺼이, {name}. 축복은 절대 안 모자라오. 마나는 가끔 모자라지만."
L["The Light asks nothing in return, {name}. I, however, accept thanks."] = "빛은 대가를 바라지 않소, {name}. 난 감사 인사 정도는 받지만."
L["Go with the Light, {name}. I'll be right behind you, clanking."] = "빛과 함께 가시오, {name}. 난 바로 뒤에서 철컹거리며 따라가겠소."
L["The blessing's free, {name}. You've been spared the sermon. This time."] = "축복은 공짜요, {name}. 설교는 봐 드리리다. 이번만."
L["There, {name}. It won't last forever, so be heroic while it does."] = "됐소, {name}. 영원하진 않으니, 효과 있을 때 영웅답게 구시오."
L["Stand tall, {name}. The Light walks with you, and it has excellent posture."] = "허리를 펴시오, {name}. 빛이 함께 걷는데, 빛은 자세가 아주 바르오."
L["You're blessed, {name}. If I bubble later, it's strictly tactical."] = "축복을 내렸소, {name}. 나중에 내가 무적 쓰면 순전히 전술이오."
L["Stand fast, {name}. We have the Light, and I have a very large hammer."] = "버티시오, {name}. 우리에겐 빛이 있고, 내겐 아주 큰 망치가 있소."
L["One blessing each, {name}. The Light is generous, but it insists on turns."] = "한 사람에 축복 하나씩이오, {name}. 빛은 너그럽지만 줄은 서야 하오."
L["Splendid, {name}. Now, nobody look directly at me. I'm rather bright today."] = "훌륭하오, {name}. 이제 아무도 날 똑바로 보지 마시오. 오늘 좀 눈부시오."
L["How kind, {name}. My imp says thank you too. He's lying, but I'm not."] = "친절하구려, {name}. 내 임프도 고맙다 하오. 그놈은 거짓말이지만 난 진심이오."
L["Thank you, {name}. It's been ages since anyone gave me something uncursed."] = "고맙소, {name}. 저주 안 걸린 걸 받아 본 게 얼마 만인지."
L["Thank you, {name}. I'll repay you with something I didn't find in a crypt."] = "고맙소, {name}. 지하 묘지에서 주운 게 아닌 걸로 갚겠소."
L["Most gracious, {name}. I've asked the voidwalker to stop looming at you."] = "고맙소, {name}. 공허방랑자한테 그대 곁에서 어른대지 말라 일러 뒀소."
L["Of course, {name}. No soul required. This time."] = "물론이오, {name}. 영혼은 필요 없소. 이번엔."
L["You asked a warlock for help, {name}. Bold. I like you already."] = "흑마법사한테 도움을 청하다니, {name}. 대담하군. 벌써 마음에 드오."
L["Of course, {name}. The imp offered to help, and I said no, for all our sakes."] = "물론이오, {name}. 임프가 돕겠다길래 말렸소. 우리 모두를 위해서."
L["Certainly, {name}. Of all my spells, this is the one I can do at parties."] = "물론이오, {name}. 내 주문 중 잔치에서 써도 되는 건 이거 하나요."
L["Here, {name}. Don't ask where it came from. Really, don't."] = "여기, {name}. 어디서 났는지는 묻지 마시오. 정말로."
L["Fall in a lake someday, {name}, and you'll think of me fondly."] = "언젠가 호수에 빠지면, {name}, 날 좋게 떠올릴 거요."
L["Breathe easy, {name}. I'd hate to lose you to anything as dull as water."] = "편히 숨 쉬시오, {name}. 물 따위 시시한 걸로 그대를 잃긴 싫소."
L["Here, {name}. You'll want a soulstone too, but that's a bigger conversation."] = "여기, {name}. 영혼석도 필요하겠지만, 그건 긴 얘기가 될 거요."
L["Take this, {name}. It's the only spell of mine the priests approve of."] = "받으시오, {name}. 사제들이 인정하는 내 주문은 이거 하나요."
L["Everyone ready, {name}? Souls intact? Good. Let's keep it that way."] = "다들 준비됐소, {name}? 영혼은 멀쩡하고? 좋소. 계속 그렇게 갑시다."
L["Stay close, {name}. The voidwalker takes the hits; I take the credit."] = "가까이 붙으시오, {name}. 맞는 건 공허방랑자, 공은 내가 챙기오."
L["Swim all you like, {name}. If anyone drifts off, I'll summon them back."] = "마음껏 헤엄치시오, {name}. 누가 떠내려가면 소환해 오겠소."
L["Do pet the felhunter, {name}. Just take your spells off first."] = "지옥사냥개 쓰다듬어도 되오, {name}. 몸에 걸린 주문은 먼저 떼고."
L["Thank you, {name}! Sorry, was that loud? I only have the one volume."] = "고맙소, {name}! 아, 시끄러웠소? 내 목소린 볼륨이 하나뿐이라."
L["Much obliged, {name}. No spells to give back, but I do a very sincere shout."] = "신세 졌소, {name}. 돌려줄 주문은 없지만, 진심 어린 외침은 있소."
L["Thanks, {name}. Now I'm twice as angry. In the good way."] = "고맙소, {name}. 덕분에 분노가 두 배요. 좋은 쪽으로."
L["Thanks, {name}. You've earned a place right behind me. Safest spot there is."] = "고맙소, {name}. 내 바로 뒷자리를 내드리리다. 세상에서 제일 안전한 곳이오."
L["You want a shout, {name}? I was going to shout anyway."] = "외쳐 달라고, {name}? 어차피 외칠 참이었소."
L["Of course, {name}. Cover your ears; this is the only way I know how."] = "물론이오, {name}. 귀 막으시오. 난 이 방법밖에 모르오."
L["Right away, {name}. Stay in earshot. For me that's a generous distance."] = "당장 하리다, {name}. 들리는 데 있으시오. 내 목청이면 꽤 멀어도 되오."
L["Happily, {name}! Words aren't my strength. Volume is."] = "기꺼이, {name}! 말솜씨는 없소. 목청은 있지."
L["Consider yourself shouted at, {name}. Affectionately."] = "방금 그대에게 외쳤소, {name}. 애정을 담아서."
L["No incense, no prayers, {name}. Just me, shouting encouragingly."] = "향도 기도도 없소, {name}. 그냥 내가 응원 삼아 소리칠 뿐."
L["Chin up, {name}! If anything bothers you, I'll charge it."] = "기운 내시오, {name}! 누가 귀찮게 하면 내가 돌진하리다."
L["There, {name}! Anything that doesn't feel braver now wasn't listening."] = "됐소, {name}! 주변에 아직 겁먹은 게 있다면 못 들은 거요."
L["Here, {name}, some courage. Warriors make it by yelling. Don't ask how."] = "여기 용기요, {name}. 전사는 고함쳐서 만드오. 어떻게냐고는 묻지 마시오."
L["Listen up, {name}! That's it. That was the whole speech."] = "잘 들으시오, {name}! 끝. 이게 연설 전부요."
L["Where's the danger, {name}? Never mind, I'll find it. Face first."] = "위험이 어디 있소, {name}? 됐소, 내가 찾겠소. 얼굴부터 들이밀어서."
L["Right, {name}! I go first, I shout loudest, and nobody touches the healer."] = "좋소, {name}! 내가 먼저 가고, 제일 크게 외치고, 힐러는 아무도 못 건드리오."
L["Everybody angrier? Good. Onward, {name}, and mind my backswing."] = "다들 화났소? 좋소. 전진이오, {name}. 내 휘두르는 반경은 조심하고."
L["A sharper mind for you, {name}. Mine cost me an eyebrow in Dalaran."] = "더 예리한 머리를 드리오, {name}. 난 달라란에서 눈썹 한쪽을 대가로 치렀소."
L["More mana for you, {name}. Try not to spend it all on one fireball."] = "마나를 더 드리오, {name}. 화염구 한 방에 다 쓰진 마시오."
L["Thoughts humming, {name}? Normal. If they hum back, come and find me."] = "머릿속이 웅웅거리오, {name}? 정상이오. 생각이 말대꾸하면 날 찾아오시오."
L["A little arcane for your thoughts, {name}. Keep the change."] = "그대 생각에 비전 한 스푼, {name}. 거스름돈은 넣어 두시오."
L["Brilliance, bottled, {name}. The Kirin Tor would charge you for the bottle."] = "총명함을 병에 담았소, {name}. 키린 토라면 병값까지 받았을 거요."
L["Sharper wits, {name}. Spend them on spells, locks or riddles; I won't judge."] = "머리가 좋아졌소, {name}. 주문에 쓰든 자물쇠든 수수께끼든, 참견 않겠소."
L["Fortitude, {name}: a priest's polite way of saying 'stand in front'."] = "인내란, {name}, '앞에 서시오'를 사제가 공손하게 하는 말이오."
L["Every bit of stamina is one less panicked prayer from me, {name}."] = "체력이 늘 때마다 내 다급한 기도가 하나씩 준다오, {name}."
L["Tougher already, {name}. Please don't take that as a dare."] = "벌써 튼튼해졌소, {name}. 그렇다고 시험해 보진 마시오."
L["There are other Power Words, {name}. 'Shield', and in emergencies, 'Run'."] = "신의 권능은 더 있소, {name}. '보호막', 급할 땐 '튀어'."
L["Sturdier now, {name}. Falls, bears and bad decisions all hurt a bit less."] = "더 단단해졌소, {name}. 낙하도, 곰도, 잘못된 선택도 덜 아플 거요."
L["{buff}, {name}. Three words where 'be tougher' would do."] = "{buff}, {name}. '버텨' 두 글자면 될 걸 참 길게도 부르오."
L["Consider your spirits lifted, {name}. Divinely, as it happens."] = "정신 번쩍 들게 해 드렸소, {name}. 천상의 방식으로."
L["Like a good night's sleep, {name}, without all the lying down."] = "푹 자고 난 것 같을 거요, {name}. 누울 필요도 없이."
L["A second helping of spirit, {name}. The Light always insists on seconds."] = "정신 한 그릇 더, {name}. 빛은 할머니처럼 늘 더 먹으라 하오."
L["Keep your spirit where it is, {name}. The Spirit Healers are busy enough."] = "영혼은 제자리에 두시오, {name}. 영혼의 치유사는 안 그래도 바쁘오."
L["Proof against shadow, {name}. I know its tricks; I've borrowed a few."] = "암흑을 막아 줄 거요, {name}. 수법은 잘 아오. 몇 개 빌려 써 봤으니."
L["Should the Void call, {name}, you can now pretend you're out."] = "공허가 부르거든, {name}, 이제 부재중인 척하면 되오."
L["For when the dark gets personal, {name}. It usually does."] = "어둠이 사적으로 덤빌 때를 위해서요, {name}. 대개 그렇게 덤비오."
L["The shadows will have to knock first now, {name}."] = "이제 그림자도 노크부터 해야 할 거요, {name}."
L["Marked by the wild, {name}. The deer will tip their antlers as you pass."] = "야생의 징표요, {name}. 지나가면 사슴들이 뿔을 까딱여 인사할 거요."
L["You may smell faintly of moss, {name}. That's how you know it's working."] = "이끼 냄새가 살짝 날 거요, {name}. 효과가 있다는 증거지."
L["Mark of the Wild, {name}. The wolves will still bite, but they'll feel bad."] = "야생의 징표요, {name}. 늑대가 물긴 하겠지만 미안해할 거요."
L["The wild's own seal of approval, {name}. The squirrels were consulted."] = "야생이 보증하는 도장이오, {name}. 다람쥐들과도 협의했소."
L["A little of the wild in you now, {name}. Resist the urge to howl."] = "이제 그대 안에 야생이 좀 깃들었소, {name}. 울부짖고 싶어도 참으시오."
L["Hide, claw and a thick coat, {name}. The wild packs light but thorough."] = "질긴 가죽, 날카로운 발톱, 두툼한 털. 야생은 짐을 가볍고 꼼꼼히 싸오, {name}."
L["Anything that bites you now gets a mouthful, {name}."] = "이제 그대를 무는 놈은 입안 가득 가시를 머금을 거요, {name}."
L["Let the boar charge, {name}. It'll leave with regrets and splinters."] = "멧돼지더러 돌진하라 하시오, {name}. 후회와 가시를 잔뜩 안고 갈 테니."
L["Like a rose, {name}: lovely to look at, a mistake to grab."] = "장미 같구려, {name}. 보기엔 곱지만 움켜쥐면 큰일 나오."
L["Thorns, {name}. I grew them myself, so do be polite to them."] = "가시요, {name}. 내가 직접 키웠으니 예쁘게 대해 주시오."
L["Blessing of Kings, {name}. No crown, no throne, no taxes owed."] = "왕의 축복이오, {name}. 왕관도, 옥좌도, 세금도 없소."
L["Long may you reign, {name}. For the next while, anyway."] = "{name} 만세! 효과가 끝날 때까지만."
L["A little more of everything, {name}. Kings never did settle for less."] = "모든 게 조금씩 더, {name}. 왕들은 원래 덜 받는 법이 없었지."
L["A king's blessing, {name}. Worn by better heads than mine, and some worse."] = "왕의 축복이오, {name}. 나보다 나은 머리들이 썼던 거요. 못한 머리도 좀 있었고."
L["Every strength a little higher, {name}. Kings like to hedge their bets."] = "모든 능력치를 조금씩 올렸소, {name}. 왕들은 분산 투자를 좋아하거든."
L["Crown not included, {name}. Everything else is, a little."] = "왕관은 별매요, {name}. 나머진 조금씩 다 들어 있소."
L["Might doesn't make right, {name}, but it does help the argument."] = "힘이 정의는 아니오, {name}. 그래도 주먹은 법보다 가깝지."
L["A firmer swing for you, {name}. The Light loves a good follow-through."] = "휘두르는 힘을 더해 드리오, {name}. 빛은 끝까지 휘두르는 걸 좋아하오."
L["Stronger arms, {name}. Kindly point them at something that deserves it."] = "팔 힘이 세졌소, {name}. 부디 맞을 만한 놈에게만 쓰시오."
L["Blessing of Might, {name}. It'll surprise you. It'll surprise them far more."] = "힘의 축복이오, {name}. 그대도 놀라겠지만, 적은 훨씬 더 놀랄 거요."
L["Swing away, {name}. The Light will take the credit if it goes well."] = "마음껏 휘두르시오, {name}. 잘되면 빛 덕, 못되면 조상 탓이오."
L["Hit harder, {name}. Them, I mean. Not me. Never the paladin."] = "더 세게 치시오, {name}. 적 말이오. 나 말고. 성기사는 절대 아니고."
L["Wisdom for you, {name}. I kept a little back for myself. Very little."] = "지혜를 드리오, {name}. 내 몫도 조금 남겨 뒀소. 아주 조금."
L["Wisdom for your mana, {name}. The other kind still comes from bad decisions."] = "마나에 지혜를, {name}. 다른 지혜는 여전히 쓴맛을 봐야 생기오."
L["Your mana creeps back on its own now, {name}, like a cat that's forgiven you."] = "이제 마나가 알아서 돌아오오, {name}. 삐졌다 풀린 고양이처럼."
L["Fewer sips between fights, {name}. The innkeepers will be heartbroken."] = "전투 사이에 물 마실 일이 줄 거요, {name}. 여관 주인들이 울겠구려."
L["Drink less, cast more, {name}. The Light's own budget advice."] = "덜 마시고 더 시전하시오, {name}. 빛이 알려 주는 절약 비법이오."
L["Blessing of Wisdom, {name}: the one blessing that pays for itself."] = "지혜의 축복이오, {name}. 본전 뽑는 유일한 축복이지."
L["A blessing of quiet, {name}. Monsters will forget whose fault it was."] = "고요의 축복이오, {name}. 괴물들이 누구 탓이었는지 잊을 거요."
L["Blessing of Salvation, {name}. You are now somebody else's problem."] = "구원의 축복이오, {name}. 이제 그대 문제는 남의 문제요."
L["Saved, {name}. Not your soul, mind. Just your hide."] = "구원받았소, {name}. 영혼은 말고, 몸뚱이만."
L["Hit hard, {name}. If anything turns round, look innocent. The Light will."] = "세게 치시오, {name}. 누가 돌아보면 모르는 척. 빛도 그럴 거요."
L["The Light will find you easier now, {name}. Try not to squint."] = "이제 빛이 그대를 더 쉽게 찾을 거요, {name}. 눈부셔도 찡그리지 마시오."
L["Holy Light lands harder on you now, {name}. Please don't make me prove it."] = "이제 성스러운 빛이 더 잘 들을 거요, {name}. 증명할 일은 없게 해 주시오."
L["You'll heal easier, {name}. The Light appreciates a willing patient."] = "치유가 잘 먹힐 거요, {name}. 빛은 협조적인 환자를 좋아하오."
L["Blessing of Light, {name}. Saving you is simpler now. Not that you'll need it."] = "빛의 축복이오, {name}. 이제 살리기 쉬워졌소. 그럴 일은 없겠지만."
L["Block a blow now, {name}, and the Light hits back for you. It's petty."] = "이제 공격을 막아 내면 빛이 대신 되갚아 주오, {name}. 뒤끝 있는 빛이지."
L["Every blow lands softer now, {name}. Complaints go to the Light."] = "이제 모든 타격이 약해질 거요, {name}. 불만은 빛에게 접수하시오."
L["All the shelter of a temple, {name}, and none of the roof repairs."] = "사원만큼 든든하오, {name}. 지붕 수리비는 없이."
L["Claim sanctuary, {name}. It's easier when you bring your own."] = "성역을 누리시오, {name}. 들고 다니니 훨씬 편하오."
L["Instructions, {name}: hit things harder. There is no page two."] = "지시 사항이오, {name}. 더 세게 칠 것. 2쪽은 없소."
L["Your sword arm is sorted, {name}. For the rest of you, see a priest."] = "칼 쥔 팔은 해결됐소, {name}. 나머지는 사제한테 가 보시오."
L["Battle Shout, {name}. Not a spell, really. A strongly worded suggestion."] = "전투의 외침이오, {name}. 주문이라기보단 아주 강력한 권유지."
L["RAAAGH! That one was for you, {name}. Everyone else just overheard."] = "으아아아! 이건 그대한테 한 거요, {name}. 다른 이들은 엿들은 거고."
L["A little breath from the damned, {name}. They weren't using it."] = "망자들의 숨을 좀 빌렸소, {name}. 어차피 안 쓰더군."
L["Unending Breath, {name}. The fish will have so many questions."] = "숨이 끝없이 이어질 거요, {name}. 물고기들이 물어볼 게 많겠구려."
L["Stay down as long as you like, {name}. Something else is holding its breath."] = "물속에 얼마든지 있으시오, {name}. 숨은 딴 녀석이 대신 참고 있으니."
L["Swim deep, {name}. If a murloc asks, you're only visiting."] = "깊이 헤엄치시오, {name}. 멀록이 물으면 잠깐 놀러 왔다 하시오."
L["Folk will think we're duelling, {name}. Thanks for the {gift}."] = "주고받는 걸 보면 결투하는 줄 알겠소, {name}. {gift} 고맙소."
L["{gift} for {buff}. No auctioneer's cut, {name}."] = "{gift} 받고 {buff} 드리오. 경매 수수료는 없소, {name}."
L["Beaten to it, {name}! Your {gift} was quicker than my manners."] = "선수를 뺏겼구려, {name}! 그대의 {gift}, 내 예의보다 빨랐소."
L["{gift} in, {buff} out. Finest economy in all Azeroth."] = "{gift} 들어오고 {buff} 나가고. 아제로스 최고의 경제요."
L["{gift}, for me? All I have is this, {name}, but it's heartfelt."] = "{gift}, 날 위해? 줄 건 이것뿐이오, {name}. 그래도 진심이오."
L["Your {gift} fits perfectly, {name}. Did you measure me?"] = "그대의 {gift}, 몸에 꼭 맞소, {name}. 치수라도 재 갔소?"
L["A treaty in spells, {name}: {gift} for {buff}."] = "주문 조약을 맺읍시다, {name}. {gift} 대 {buff}."
L["{gift}! I feel taller already. Have some {buff}."] = "{gift}! 벌써 키가 큰 기분이오. {buff}도 받으시오."
L["I was about to ask for {gift}, {name}. You read my mind."] = "막 {gift} 부탁하려던 참이오, {name}. 내 마음을 읽었구려."
L["Your {gift} still fizzes, {name}. Here's some fizz back."] = "그대의 {gift}, 아직 톡톡 튀는구려, {name}. 나도 톡 쏘는 걸로 답하리다."
L["Such a kind {gift}, {name}. I'll tell the whole inn. Twice."] = "다정하기도 하지, {name}. 이 {gift} 얘기, 여관에 다 퍼뜨리겠소. 두 번씩."
L["You cast {gift} first, {name}? My mother would despair of me."] = "그대가 먼저 {gift} 시전을? 어머니가 아시면 한숨 쉬시겠소, {name}."
L["I'll remember your {gift} fondly, {name}. Until it wears off."] = "그대의 {gift}, 두고두고 기억하리다, {name}. 효과가 끝날 때까지는."
L["{gift} for {buff}, free. Somewhere, a goblin weeps."] = "{gift} 받고 {buff} 드리오. 공짜로. 어디선가 고블린이 우는구려."
L["Your {gift}, my {buff}. We'll be unbearable now."] = "그대의 {gift}, 나의 {buff}. 이제 우리 못 말리겠구려."
L["Thanks for the {gift}, {name}. I'll earn it before it fades."] = "{gift} 고맙소, {name}. 효과 끝나기 전에 밥값은 하겠소."
L["For {gift} I'd hand you both moons, {name}. This'll have to do."] = "{gift} 보답으론 달 두 개라도 따 드리고 싶소만, {name}. 이걸로 참으시오."
L["You brought {gift}, I brought {buff}. Now it's a party."] = "그대는 {gift}, 나는 {buff}. 이제 제대로 잔치구려."
L["{gift}! I just had three clever thoughts, {name}. This was one."] = "{gift}! 방금 똑똑한 생각이 세 개나 났소, {name}. 이게 그중 하나요."
L["With {gift}, {name}, I finally understand my own notes. Thanks."] = "{gift} 덕에, {name}, 드디어 내 메모를 알아보겠소. 고맙소."
L["Cleverer already, {name}. Clever enough to know I owe you one. Here."] = "벌써 똑똑해졌소, {name}. 신세 진 걸 알 만큼은. 여기."
L["{gift}, {name}? I'll stand at the front for once. Briefly."] = "{gift}, {name}? 이번만은 앞에 서 보겠소. 잠깐만."
L["Knees, elbows and pride, {name}: all fortified. Thank you."] = "무릎, 팔꿈치, 자존심까지 다 튼튼해졌소, {name}. 고맙소."
L["Hit me now, {name}. Actually, don't. But thank you; I'd survive it."] = "이제 날 쳐 보시오, {name}. 아니, 치진 마시오. 그래도 버틸 거요. 고맙소."
L["{gift}! My spirits are lifted, {name}. Literally, it seems."] = "{gift}! 정신이 고양되오, {name}. 말 그대로 정신이."
L["I feel twice as calm and half as grumpy, {name}. Thank you."] = "두 배로 차분하고 절반만 투덜대게 됐소, {name}. 고맙소."
L["Shadow-proof, thanks to you, {name}. The whispers are furious."] = "덕분에 암흑이 안 통하오, {name}. 속삭임들이 잔뜩 성났소."
L["Nothing dark gets in now, {name}. Here's something bright going the other way."] = "이제 어둠은 못 들어오오, {name}. 대신 밝은 걸 내보내리다."
L["{gift}! A squirrel just nodded at me, {name}. Here's yours."] = "{gift}! 방금 다람쥐가 내게 고개를 까딱했소, {name}. 이건 그대 몫이오."
L["Tougher hide, sharper senses, {name}. I may have to fight the urge to forage."] = "가죽은 질기고 감각은 예리해졌소, {name}. 도토리 줍고 싶은 걸 참아야겠구려."
L["I feel all wild and leafy, {name}. Thank you. Sorry if I shed bark."] = "온몸에 잎이 돋는 기분이오, {name}. 고맙소. 나무껍질 떨어지면 미안하오."
L["{gift}, {name}! Nobody's hugging me today. Have this instead."] = "{gift}, {name}! 오늘은 아무도 날 못 안겠구려. 대신 이거라도."
L["Prickly now, thanks to you, {name}. More than usual, I mean."] = "덕분에 가시가 돋쳤소, {name}. 평소엔 말에만 있었는데."
L["{gift} from you, {name}? I'll try not to found a dynasty."] = "{gift}, 그대가 주는 거요, {name}? 왕조는 안 세우도록 조심하리다."
L["A little better at everything, {name}. Is this how kings feel? No wonder."] = "모든 게 조금씩 나아졌소, {name}. 왕들은 이런 기분이었구려. 어쩐지."
L["Stronger arms already, {name}. I'll try not to hug anyone. Thank you."] = "벌써 팔 힘이 세졌소, {name}. 아무도 안 안도록 조심하리다. 고맙소."
L["With {gift} I could lift a kodo, {name}. I won't, but thank you."] = "{gift} 덕에 코도도 들겠소, {name}. 안 들겠지만, 고맙소."
L["{gift} from you, {name}, and my first wise act is this."] = "그대의 {gift}, 고맙소, {name}. 지혜로워진 내 첫 행동이 바로 이거요."
L["Wiser already, {name}. Wise enough to know a kindness when I see one."] = "벌써 지혜로워졌소, {name}. 친절을 알아볼 만큼은."
L["{gift}! The monsters forgot me at once, {name}. I won't."] = "{gift}! 괴물들은 날 바로 잊었소, {name}. 난 안 잊겠지만."
L["Nothing wants to fight me now, {name}. It's lovely. Thank you."] = "이제 아무도 나랑 안 싸우려 하오, {name}. 참 좋구려. 고맙소."
L["The Light finds me easier now, {name}. It says thank you, and so do I."] = "이제 빛이 날 더 쉽게 찾소, {name}. 빛도 고맙다 하고, 나도 고맙소."
L["Easier to heal now, thanks to you, {name}. My healer thanks you too."] = "덕분에 치유가 잘 먹히오, {name}. 우리 힐러도 고맙다 하오."
L["Blows land softer on me now, {name}. My bruises thank you, and so do I."] = "이제 맞아도 덜 아프오, {name}. 멍들도 고맙다 하고, 나도 고맙소."
L["Every hit gentler, thanks to you, {name}. I'll make sure they notice."] = "덕분에 타격이 한결 부드럽소, {name}. 놈들도 알아채게 해 주리다."
L["You shouted at me, {name}, and I've never felt so encouraged. Here."] = "그대가 내게 소리쳤는데, {name}, 이렇게 힘이 난 적은 처음이오. 여기."
L["My ears are ringing, {name}, and my arms feel twice as strong. Thank you!"] = "귀는 멍멍하고 팔 힘은 두 배요, {name}. 고맙소!"
L["I can breathe underwater, {name}! I may never need to, but thank you."] = "물속에서 숨을 쉴 수 있소, {name}! 쓸 일은 없을지 몰라도, 고맙소."
L["Lungs like a murloc, thanks to you, {name}. Mrgl. Sorry. Thank you."] = "덕분에 폐활량이 멀록급이오, {name}. 므르글. 아, 미안. 고맙소."
L["We have to stop meeting like this, {name}. Actually, no, we don't."] = "이렇게 자꾸 만나면 곤란하오, {name}. 아니, 곤란할 거 없구려."
L["Again, {name}? Splendid. I've been practising since last time."] = "또 만났소, {name}? 좋구려. 지난번 이후로 연습해 뒀소."
L["You again, {name}? People will start saying we're friends."] = "또 그대요, {name}? 사람들이 우리 친구라고 수군대겠소."
L["Same face, same spell, {name}. I do love a tradition."] = "같은 얼굴, 같은 주문이오, {name}. 난 전통이 참 좋소."
L["Another round, {name}? I'm keeping score, and we're both winning."] = "한 판 더, {name}? 점수를 세고 있는데, 둘 다 이기는 중이오."
L["Ah, {name}! My favourite repeat customer."] = "아, {name}! 내가 제일 아끼는 단골손님."
L["Our paths keep crossing, {name}. I think the road is dropping hints."] = "자꾸 길이 겹치는구려, {name}. 옷깃만 스쳐도 인연이라던데."
L["Hello again, {name}. Do stop me if you've heard this one."] = "또 만났구려, {name}. 이 얘기 들은 적 있으면 말리시오."
L["I kept some aside, {name}, in case you came back. Good instinct, mine."] = "그대가 다시 올까 봐 좀 남겨 뒀소, {name}. 내 감이 좋았구려."
L["Back already, {name}? I'm starting to think you like me."] = "벌써 돌아왔소, {name}? 날 좋아하는 게 아닌가 싶구려."
L["{name}, at this point we should just share a reagent pouch."] = "{name}, 이쯤 되면 재료 주머니를 같이 써야겠소."
L["Same time tomorrow, {name}? I'll bring {buff}. You bring you."] = "내일 이 시간에, {name}? 난 {buff}, 그대는 그대만 가져오시오."
L["I've lost count, {name}, and I've decided that's a compliment."] = "몇 번째인지 세다 놓쳤소, {name}. 칭찬으로 받아 주시오."
L["Keep this up, {name}, and the bards will write a very dull song about us."] = "이대로 가면, {name}, 음유시인들이 우리 얘기로 아주 지루한 노래를 쓰겠소."
L["I could do this one in my sleep by now, {name}. I may have."] = "이젠 자면서도 하겠소, {name}. 이미 그랬을지도."
L["{name}, the usual? Of course the usual. It's always the usual."] = "{name}, 늘 먹던 걸로? 물론 늘 먹던 걸로. 언제나 늘 먹던 거지."
L["We ought to have a secret handshake by now, {name}. Next time, perhaps."] = "이쯤이면 우리만의 비밀 악수가 있어야 하오, {name}. 다음엔 만들어 봅시다."
L["By now, {name}, I think we've built a small economy between us."] = "이쯤 되니, {name}, 우리 둘이 작은 경제를 이룬 것 같소."
L["Old friends by now, {name}. Well, old acquaintances with excellent timing."] = "이제 오랜 친구요, {name}. 아니, 타이밍 기막힌 오랜 지인이랄까."
L["Let the record show: {name} and I, undefeated at being prepared."] = "기록해 두시오. {name}하고 나, 준비성 부문 무패."
L["Safe walls, warm beds, and now {buff}. You're spoiled, {name}."] = "튼튼한 성벽, 따뜻한 침대, 이제 {buff}까지. 호강하는구려, {name}."
L["The guards have it covered, {name}, but I like to be thorough."] = "경비병이 지켜 주겠지만, {name}, 난 꼼꼼한 게 좋소."
L["Careful, {name}. Look this capable in town and folk will ask you favours."] = "조심하시오, {name}. 마을에서 이리 유능해 보이면 다들 부탁하러 올 거요."
L["Not a monster for miles, {name}. Still, one never knows about the cooking."] = "근방에 괴물은 없소, {name}. 그래도 여기 요리는 모를 일이오."
L["For the crowds, {name}. In town, they're the real danger."] = "인파 대비용이오, {name}. 도시에선 그게 진짜 위험이지."
L["Rest easy, {name}. I'll count that my good deed and go find a pint."] = "편히 쉬시오, {name}. 이걸로 오늘 선행은 했으니 한잔하러 가겠소."
L["Even in town, {name}, a dragon has been known to drop in. Better safe."] = "도시에도 가끔 용이 들이닥친다오, {name}. 조심해서 나쁠 건 없지."
L["Best do it in here, {name}. Out there, nobody stands still long enough."] = "여기서 하는 게 낫소, {name}. 밖에선 아무도 가만있질 않으니."
L["Out here everything wants to eat you, {name}. Now it'll need a bigger fork."] = "여기선 뭐든 그대를 먹으려 드오, {name}. 이제 더 큰 포크가 필요할 거요."
L["No guards for miles, {name}, and the boars know it. Take this."] = "근방에 경비병 하나 없소, {name}. 멧돼지들도 그걸 알지. 받으시오."
L["Nobody out here but us and the wildlife, {name}. Let's be the tougher half."] = "여긴 우리랑 짐승들뿐이오, {name}. 우리가 더 센 쪽이 됩시다."
L["If a bear asks, {name}, you were like this when I found you."] = "곰이 물으면, {name}, 원래부터 이랬다고 하시오."
L["The wolves have been eyeing you, {name}. This should give them pause."] = "늑대들이 그대를 노리던데, {name}. 이러면 좀 망설이겠지."
L["Wild country, {name}. Best not to meet it armed with good intentions alone."] = "험한 땅이오, {name}. 좋은 뜻만 들고 맞서긴 곤란하오."
L["Map, canteen, {buff}. Now you can get lost properly, {name}."] = "지도, 물통, {buff}. 이제 제대로 길을 잃어도 되오, {name}."
L["Camp's a long way off, {name}. Consider this a roof you can carry."] = "야영지는 한참 멀었소, {name}. 들고 다니는 지붕이라 생각하시오."
L["Somewhere in here a villain is rehearsing a speech, {name}. Let's interrupt."] = "이 안 어딘가서 악당이 연설 연습 중이오, {name}. 가서 끊어 줍시다."
L["Whatever waits at the end of this place, {name}, let's make it regret it."] = "이 끝에 뭐가 기다리든, {name}, 후회하게 만들어 줍시다."
L["They say nobody leaves here alive, {name}. Let's be rude and prove them wrong."] = "여기선 아무도 살아 나가지 못한다더군, {name}. 무례하게 반박해 줍시다."
L["Our host had years to prepare, {name}. We have {buff}."] = "이곳 주인은 몇 년을 준비했소, {name}. 우리에겐 {buff}."
L["Nobody builds a dungeon with a back door, {name}. Take this instead."] = "뒷문 달린 던전은 없소, {name}. 대신 이걸 받으시오."
L["Dark halls, old traps, worse tempers. At least you're ready, {name}."] = "어두운 복도, 낡은 함정, 더 고약한 성질머리. 적어도 그대는 준비됐소, {name}."
L["Better I hand you this now, {name}, than a eulogy later."] = "나중에 추도사를 바치느니, {name}, 지금 이걸 드리는 게 낫소."
L["There's treasure in here, {name}, and something very large sat on it."] = "여기 보물이 있소, {name}. 아주 큰 뭔가가 깔고 앉아 있지만."
L["Flags, towers, graveyards, {name}. Whatever we're fighting over, take this."] = "깃발, 탑, 무덤, {name}. 뭘 두고 싸우든, 이걸 받으시오."
L["Win or lose, {name}, nobody will say you went in unprepared."] = "이기든 지든, {name}, 준비 없이 갔단 말은 안 나올 거요."
L["The graveyard's just over there, {name}. Let's both not visit it."] = "무덤은 바로 저기요, {name}. 둘 다 들르지 맙시다."
L["Honour's on the line, {name}. So is the flag. Mostly the flag."] = "명예가 걸렸소, {name}. 깃발도 걸렸고. 주로 깃발이."
L["Stay with the group, {name}. Lone heroes end up in the other side's songs."] = "무리와 함께 있으시오, {name}. 홀로 나선 영웅은 적의 노래에 나오오."
L["Early bird, {name}? Here's something better than a worm."] = "일찍 일어난 새구려, {name}. 벌레보다 나은 걸 드리리다."
L["Good morning, {name}. Consider this your first cup of something strong."] = "좋은 아침이오, {name}. 오늘의 첫 진한 차 한 잔이라 치시오."
L["Early start, {name}. The day hasn't had a chance to go wrong yet."] = "일찍 나섰구려, {name}. 하루가 아직 꼬일 틈도 없었소."
L["Not even lunch yet, {name}, and you're already better prepared than I am."] = "점심도 안 됐는데, {name}, 벌써 나보다 준비가 잘됐구려."
L["Morning, {name}. Somewhere, the monsters are still yawning."] = "좋은 아침, {name}. 어디선가 괴물들은 아직 하품 중이오."
L["A fresh day and a fresh {buff}, {name}. Let's not waste either."] = "새 하루에 새 {buff}, {name}. 둘 다 허투루 쓰지 맙시다."
L["Out this late, {name}? The night is hungrier than the day. Take this."] = "이 늦은 시간에, {name}? 밤은 낮보다 굶주렸소. 받으시오."
L["Past bedtime, {name}. The sensible folk are asleep, which leaves us."] = "잘 시간이 지났소, {name}. 분별 있는 이들은 다 잠들었으니, 남은 건 우리요."
L["Can't sleep either, {name}? Then let's be well-protected insomniacs."] = "그대도 잠이 안 오오, {name}? 그럼 든든하게 무장한 불면증 환자가 됩시다."
L["Mind the dark, {name}. Not everything out there is as friendly as I am."] = "어둠을 조심하시오, {name}. 밖엔 나처럼 친절한 것만 있지 않소."
L["It's late, {name}. This should keep you going till the sun remembers us."] = "늦었소, {name}. 해가 우릴 기억해 낼 때까진 이걸로 버티시오."
L["Only the owls and us awake, {name}, and the owls get no {buff}."] = "깨어 있는 건 부엉이와 우리뿐이오, {name}. 부엉이한텐 {buff} 없소."
L["Takes one to know one, {name}. Takes one to do it properly, too."] = "알아보는 건 같은 직업이지, {name}. 제대로 챙기는 것도 같은 직업이고."
L["From one of our trade to another, {name}. No need to check my work."] = "동업자끼리 드리는 거요, {name}. 검수는 필요 없소."
L["Professional courtesy, {name}. We don't charge each other."] = "동업자 예우요, {name}. 우리끼린 돈 안 받소."
L["Two of a kind, {name}. Between us we could write the manual."] = "같은 부류구려, {name}. 둘이면 교본도 쓰겠소."
L["Don't look so surprised, {name}. Same trainer, I expect."] = "그리 놀라지 마시오, {name}. 같은 스승한테 배웠나 보오."
L["I'd critique your technique, {name}, but mine looks exactly the same."] = "그대 솜씨를 평하고 싶지만, {name}, 내 것도 똑같이 생겼소."
L["Don't tell the others, {name}, but ours really is the finest calling."] = "다른 이들한텐 비밀이오, {name}. 우리 직업이 사실 최고요."
L["Look at us, {name}. Two experts, making it look easy. It isn't, is it?"] = "우릴 보시오, {name}. 전문가 둘이 쉬워 보이게 하는 중이오. 사실 안 쉽잖소?"
L["I'd shout some encouragement, {name}, but you do that far better."] = "응원의 함성을 질러 주고 싶지만, {name}, 그건 그대가 훨씬 잘하지."
L["Charge in as usual, {name}. I'll simply feel better about it now."] = "늘 하던 대로 돌진하시오, {name}. 이제 내 마음이 좀 놓이겠소."
L["For the one who goes in first, {name}. Somebody has to, and it's never me."] = "맨 먼저 뛰어드는 이에게, {name}. 누군가는 해야 하고, 그게 난 아니지."
L["You take the hits so the rest of us don't, {name}. It's the least I can do."] = "우리 대신 맞아 주는 그대요, {name}. 이 정도는 해야지."
L["Go on, {name}, charge. I'll be right behind you. Quite a long way behind."] = "어서 돌진하시오, {name}. 바로 뒤따르겠소. 꽤 멀찍이 뒤에서."
L["Save the bubble for later, {name}. This one's from me."] = "무적은 아껴 두시오, {name}. 이번 건 내가 드리오."
L["You bless everyone else all day, {name}. Here's one going the other way."] = "종일 남들만 축복하잖소, {name}. 이번엔 거꾸로 드리오."
L["The Light already likes you, {name}. Consider this a second opinion."] = "빛은 이미 그대를 아끼오, {name}. 이건 두 번째 소견이라 치시오."
L["Even the Light's own champion needs a hand now and then, {name}."] = "빛의 용사에게도 가끔 도움은 필요하오, {name}."
L["I'd ask for a blessing back, {name}, but then we'd be here all day."] = "축복을 돌려 달라 하고 싶지만, {name}, 그럼 하루가 다 가겠소."
L["One for you, {name}, and a pat on the head for your companion."] = "그대에게 하나, {name}. 그대 야수에겐 머리 쓰다듬기 한 번."
L["You watch everyone's back from range, {name}. I've got yours."] = "멀리서 모두의 등을 지켜 주잖소, {name}. 그대 등은 내가 맡지."
L["Hunter's Mark for them, {buff} for you, {name}. Much nicer."] = "적에겐 사냥꾼의 징표, 그대에겐 {buff}, {name}. 훨씬 낫지."
L["Aim true, {name}. And if it charges you anyway, run towards the rest of us."] = "잘 조준하시오, {name}. 그래도 달려들면 우리 쪽으로 뛰어오시오."
L["Your pet was looking at me hopefully, {name}. This is for you; tell it sorry."] = "그대 야수가 날 애타게 보던데, {name}. 이건 그대 몫이오. 미안하다 전해 주오."
L["For the one I never see coming, {name}. Meant as the highest praise."] = "언제 오는지 도통 안 보이는 이에게, {name}. 최고의 칭찬이오."
L["Quick, {name}, before you vanish again."] = "얼른, {name}. 또 사라지기 전에."
L["Poison on the blades, {buff} on you. Very thorough, {name}."] = "칼날엔 독, 몸엔 {buff}. 아주 철저하구려, {name}."
L["I'd slip it in your pocket, {name}, but you'd notice. You always notice."] = "주머니에 슬쩍 넣어 두려 했소, {name}. 하지만 알아채겠지. 늘 알아채니까."
L["For the one who opens every locked box, {name}. This one comes unlocked."] = "잠긴 상자는 다 여는 그대에게, {name}. 이건 처음부터 열려 있소."
L["For once, {name}, somebody's looking after the priest."] = "이번만큼은, {name}, 누군가 사제를 챙기는구려."
L["Save your prayers for the rest of us, {name}. This one's already answered."] = "기도는 우리 몫으로 아껴 두시오, {name}. 이 기도는 이미 응답받았소."
L["Light or Shadow, {name}, I don't ask which. This suits both."] = "빛이든 암흑이든, {name}, 묻지 않겠소. 둘 다 어울리니."
L["Sit down after this fight, {name}. That's an order, from a grateful patient."] = "이 전투 끝나면 좀 앉으시오, {name}. 고마운 환자가 내리는 명령이오."
L["You keep us all standing, {name}. Here's a little of it coming back."] = "그대 덕에 우리가 버티잖소, {name}. 그중 조금을 돌려드리오."
L["No voice in your head comes with this one, {name}. Refreshing, isn't it?"] = "이건 머릿속 목소리가 딸려 오지 않소, {name}. 개운하지 않소?"
L["The Ebon Blade asks no favours, {name}. I'm giving one anyway."] = "칠흑의 기사단은 호의를 청하지 않지, {name}. 그래도 드리겠소."
L["A little warmth, {name}. I know you don't feel the cold. It's the thought."] = "온기 좀 드리오, {name}. 추위를 못 느끼는 건 알지만, 마음이오."
L["You came back from the dead, {name}. The least I can do is help you stay back."] = "죽음에서 돌아왔으니, {name}, 다시 안 가게 거드는 게 도리지."
L["Runes, plague and frost, {name}. Take this too; it completes the set."] = "룬, 역병, 냉기, {name}. 이것도 받으시오. 세트 완성이오."
L["The elements look after you, {name}, but they don't make house calls."] = "정령들이 그대를 돌보지만, {name}, 왕진은 안 오잖소."
L["Tell the spirits I said hello, {name}. They never write back."] = "영혼들에게 안부 전해 주시오, {name}. 내 편지엔 답장이 없어서."
L["Plant a totem in my honour, {name}. A small one. I'm modest."] = "날 기려 토템 하나 세워 주시오, {name}. 작은 걸로. 난 겸손하니."
L["Earth, fire, water, air and me, {name}. Admittedly the least of the five."] = "대지, 화염, 물, 바람, 그리고 나, {name}. 다섯 중 제일 약한 건 인정하오."
L["Totems up already, {name}? Then this goes next to them. Don't plant it."] = "벌써 토템을 세웠소, {name}? 그럼 이건 그 옆에. 심지는 마시오."
L["A gift for a mage, {name}? Like bringing water to... well, you."] = "마법사에게 선물이라, {name}? 물빵 가게에 물 사 가는 격이구려."
L["You solve most problems with sheep, {name}. This covers the rest."] = "대부분의 문제는 양으로 해결하잖소, {name}. 나머진 이걸로."
L["You could teleport out of any trouble, {name}. This is for the trouble first."] = "어떤 곤경이든 순간이동으로 빠지겠지만, {name}, 이건 빠지기 전 몫이오."
L["For the clever one, {name}. Please don't thank me by making me a sheep."] = "똑똑한 그대에게, {name}. 감사 인사로 날 양으로 만들진 마시오."
L["Blink wherever you like, {name}. This comes too."] = "어디로 점멸하든, {name}, 이건 따라가오."
L["Entirely demon-free, {name}. I checked."] = "악마 성분 0%요, {name}. 직접 확인했소."
L["Your imp may be jealous, {name}. Tell it there's plenty to go round."] = "그대 임프가 샘낼지도 모르오, {name}. 넉넉하다고 전해 주시오."
L["No contract, no fine print, {name}. Just a gift."] = "계약서도, 깨알 같은 약관도 없소, {name}. 그냥 선물이오."
L["For the one who hands out healthstones, {name}. Nobody ever thanks you."] = "생명석 나눠 주는 그대에게, {name}. 고맙단 말 한 번 못 들었을 테니."
L["Here, {name}. Summon the rest of us later and we'll call it even."] = "여기, {name}. 나중에 우리 소환해 주면 퉁칩시다."
L["Roll wherever you like, {name}. This rolls with you."] = "어디로 구르든, {name}, 이것도 같이 구르오."
L["Brew first or fight first, {name}? Either way, take this."] = "술이 먼저요, 싸움이 먼저요, {name}? 어느 쪽이든 받으시오."
L["Inner peace for you, {name}, and outer peace too, as long as this lasts."] = "그대에게 내면의 평화를, {name}. 이게 지속되는 동안은 바깥 평화도."
L["Chi flows better with a little help, {name}. Or so a monk once told me."] = "기의 흐름엔 도움이 좀 필요하오, {name}. 어느 수도사가 그러더군."
L["Kick, flip, roll, {name}. I'll just stand here and do this bit."] = "차고, 뒤집고, 구르고, {name}. 난 여기 서서 이것만 하겠소."
L["Tell the bear this is for them too, {name}."] = "곰에게도 전해 주시오, {name}. 이건 곰 몫이기도 하다고."
L["Hold still, {name}. I've never once managed to catch you as a cheetah."] = "가만있으시오, {name}. 치타일 땐 한 번도 못 잡았으니."
L["Nature looks after you already, {name}. Today she sent me to help."] = "이미 자연이 그대를 돌보지만, {name}, 오늘은 날 보냈구려."
L["Whatever shape you're in next, {name}, this goes with you."] = "다음에 무슨 모습이 되든, {name}, 이건 함께 가오."
L["For the forest's friend, {name}. Give my regards to the trees."] = "숲의 벗에게, {name}. 나무들에게 안부 전해 주시오."
L["You were not prepared, {name}. Now you are."] = "'아직 준비가 안 됐다'더니, {name}. 이제 됐소."
L["Ten thousand years in a cell, {name}. You've earned a small kindness."] = "감옥에서 만 년이라, {name}. 작은 친절쯤은 받을 만하오."
L["You gave up so much to fight the Legion, {name}. Here's a little back."] = "군단과 싸우려 많은 걸 버렸잖소, {name}. 조금 돌려드리오."
L["For the one who leaps first, {name}. Do land somewhere friendly."] = "맨 먼저 뛰어드는 그대에게, {name}. 착지는 부디 우리 편 쪽에."
L["Fel and fury, {name}, and now a little kindness. It'll balance out."] = "지옥 마력과 분노, {name}, 이제 친절도 조금. 균형이 맞을 거요."
L["For you, {name}. Please don't breathe on it."] = "그대에게, {name}. 부디 입김은 불지 마시오."
L["A little help for a dragon, {name}. I'll be telling my grandchildren."] = "용에게 도움을 주다니, {name}. 손주들한테 두고두고 자랑하겠소."
L["The Aspects sent you out into the world, {name}. I'm making it friendlier."] = "위상들이 그대를 세상에 보냈소, {name}. 난 세상을 좀 다정하게 만드는 중이오."
L["Take to the skies after this, {name}. I'll wave from down here."] = "이걸 받고 하늘로 날아오르시오, {name}. 난 여기서 손 흔들겠소."
L["A dragon on our side, {name}. I've never felt safer being generous."] = "용이 우리 편이라, {name}. 이렇게 안심하고 베풀어 본 적이 없소."
L["{buff} for a mage, {name}. Like lending a library a book."] = "마법사에게 {buff}, {name}. 도서관에 책 빌려주는 격이오."
L["Mage to mage, {name}: I won't ask you for water if you won't ask me."] = "마법사끼리 약속합시다, {name}. 서로 물 달라고는 하지 않기로."
L["Two mages, {name}. Between us we can portal anywhere and still be late."] = "마법사가 둘이오, {name}. 어디든 차원문을 열 수 있는데도 둘 다 지각하지."
L["A mage for a mage, {name}. The Kirin Tor would call this peer review."] = "마법사가 마법사에게, {name}. 키린 토라면 동료 심사라 부를 거요."
L["Priest to priest, {name}: who blesses the blessers? Today, me."] = "사제끼리 묻겠소, {name}. 축복하는 이는 누가 축복하오? 오늘은 나요."
L["Between us priests, {name}, we'll both pretend the tank listens."] = "사제끼리니까, {name}, 탱커가 말 듣는다고 서로 믿는 척합시다."
L["A priest looking after a priest, {name}. It feels almost forbidden."] = "사제가 사제를 챙기다니, {name}. 왠지 금기 같구려."
L["Two priests, {name}. Twice the praying and half the panic."] = "사제가 둘이오, {name}. 기도는 두 배, 호들갑은 절반."
L["Two druids, {name}. The Cenarion Circle would call this a quorum."] = "드루이드가 둘이오, {name}. 세나리온 의회라면 정족수를 채웠다 하겠소."
L["Druid to druid, {name}: bear or cat, I'd know you by the leaves in your hair."] = "드루이드끼리니까, {name}. 곰이든 표범이든 머리에 붙은 잎사귀로 알아보오."
L["From one shapeshifter to another, {name}: this one fits every shape."] = "변신술사끼리 드리오, {name}. 이건 어느 모습에나 맞소."
L["No handshake, {name}. Two druids, and neither of us has the right shape for it."] = "악수는 생략하오, {name}. 드루이드 둘인데 둘 다 손 있는 모습이 아니라서."
L["Paladin to paladin, {name}: I won't mention the bubble if you don't."] = "성기사끼리니까, {name}. 무적 얘긴 서로 꺼내지 맙시다."
L["A blessing for a paladin, {name}. Now we're both insufferably radiant."] = "성기사에게 축복을, {name}. 이제 둘 다 못 봐줄 만큼 눈부시오."
L["Two paladins, {name}. Somewhere, a priest is quietly relieved."] = "성기사가 둘이오, {name}. 어디선가 사제가 조용히 한숨 돌리겠구려."
L["One of us should be humble about this, {name}. Neither of us will be."] = "둘 중 하나는 겸손해야 할 텐데, {name}. 둘 다 안 그럴 거요."
L["Warlock to warlock, {name}: keep your imp away from mine. They gossip."] = "흑마법사끼리니까, {name}. 임프끼리는 떼어 놓읍시다. 수다가 심하오."
L["Fellow warlock, {name}? Then you know this one's actually harmless. Honestly."] = "흑마법사 동지요, {name}? 그럼 이게 진짜 무해한 거 알겠구려. 정말이오."
L["Two warlocks, {name}. Let's not compare soul shards in public."] = "흑마법사가 둘이오, {name}. 남들 앞에서 영혼의 조각 개수는 비교하지 맙시다."
L["Between us, {name}, the demons do all the work. This bit I do myself."] = "우리끼리 얘기지만, {name}, 일은 악마들이 다 하지. 이건 내가 직접 하오."
L["Two warriors, {name}. Somewhere, a healer just sighed."] = "전사가 둘이오, {name}. 어디선가 힐러가 한숨 쉬었소."
L["Warrior to warrior, {name}: first into the fight buys the drinks. I'm buying."] = "전사끼리 규칙이오, {name}. 먼저 뛰어든 자가 술 사기. 내가 사겠소."
L["Shout for shout, {name}. We'll deafen the whole place together."] = "외침엔 외침으로, {name}. 같이 이 동네 귀를 먹게 합시다."
L["No plan, {name}? Perfect. We'll get along."] = "작전이 없다고, {name}? 완벽하오. 우린 잘 맞겠구려."
L["Aye, {name}, ye only had to ask. Hold still now!"] = "암, {name}, 말만 하면 되지. 가만있어 보게!"
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "옜네, {name}. 쓰러지지 말라고 주는 작은 선물일세."
L["My thanks, {name}. Allow me to return the kindness."] = "고맙소, {name}. 이 호의에 보답하겠소."
L["Of course, {name}. Stand fast a moment."] = "물론이오, {name}. 잠시 그대로 서 계시오."
L["The road ahead is long, {name}. Take this with you."] = "갈 길이 멀다오, {name}. 이것을 챙겨 가시오."
L["Ishnu-alah, {name}. Your kindness is returned."] = "Ishnu-alah, {name}. 그대의 호의를 돌려드리리다."
L["Elune-adore, {name}. Walk softly beneath the stars."] = "Elune-adore, {name}. 별빛 아래 사뿐히 걷기를."
L["The Light rewards kindness, {name}, and so shall I."] = "빛이 친절에 보답하듯, 저도 보답하겠습니다, {name}."
L["Of course, {name}. May the Naaru guide your steps."] = "물론입니다, {name}. 나루께서 그대의 길을 인도하시길."
L["The Light is with you, {name}. Go in peace."] = "빛이 그대와 함께합니다, {name}. 평안히 가십시오."
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "신세 졌소, {name}. 길니아스는 은혜를 잊지 않소."
L["Lok'tar ogar, {name}! Take this into battle."] = "Lok'tar ogar, {name}! 이걸 품고 전장으로 가라!"
L["The Earth Mother sees your kindness, {name}. I return it."] = "대지모신께서 그대의 친절을 보셨소, {name}. 나도 보답하리다."
L["Of course, {name}. Stand tall and be at peace."] = "여부가 있겠소, {name}. 곧게 서서 마음을 편히 가지시오."
L["Walk with the Earth Mother, {name}."] = "대지모신과 함께 걷기를, {name}."
L["Sure ting, {name}. Hold still now."] = "암, 그렇고말고, {name}. 가만있으라고."
L["Da loa be watchin' over ya, {name}."] = "로아가 널 지켜보고 있다고, {name}."
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "그 예의, 칭찬할 만하군요, {name}. Anar'alah belore."
L["Anar'alah belore, {name}. May the sun guide you."] = "Anar'alah belore, {name}. 태양이 그대를 인도하기를."
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "그 아량, 기억하지요, {name}. 수라마르는 벗을 잊지 않으니."
L["Thank you, {name}! The caravan always repays a kindness."] = "고마워요, {name}님! 대상단은 받은 친절을 꼭 갚아요."
L["Every traveller needs something for the road, {name}."] = "나그네라면 길에서 쓸 게 필요하죠, {name}님."
L["Of course, {name}. Patience, and it is done."] = "물론이지, {name}. 조금만 참으면 다 된다네."
L["Take this, {name}. Even a dragon needs allies."] = "이걸 받으시오, {name}. 용에게도 동료는 필요하오."
L["Thank you, {name}. The Alliance looks after its own."] = "고맙소, {name}. 얼라이언스는 동료를 챙기는 법이오."
L["Of course, {name}. Allies help each other."] = "당연하오, {name}. 동맹은 서로 돕는 법이오."
L["For the Alliance, {name}! Stay strong out there."] = "얼라이언스를 위하여, {name}! 굳건히 버티시오."
L["Strength and honour, {name}. Your kindness is repaid."] = "힘과 명예를, {name}. 받은 호의는 갚았소."
L["Consider it done, {name}. For the Horde."] = "맡겨 두시오, {name}. 호드를 위하여."
L["For the Horde, {name}! Go with strength."] = "호드를 위하여, {name}! 힘이 함께하기를."
L["Thank you, {name}. Good hearts are found everywhere."] = "고맙소, {name}. 선한 마음은 어디에나 있구려."
L["Gladly, {name}, whatever banner you fly."] = "기꺼이, {name}. 그대가 어느 깃발 아래 있든."
L["Friends can come from any side, {name}."] = "벗은 어느 편에서든 오는 법이오, {name}."
L["Safe travels, {name}. Take some {buff} with you."] = "무사히 가시오, {name}. {buff}도 챙겨 가시고."
L["Returning a favour:"] = "호의에 보답할 때:"
L["Answering a request:"] = "요청에 응할 때:"
L["In your group:"] = "파티원일 때:"
L["Offering unasked:"] = "먼저 줄 때:"
L["Returning a favour of %s:"] = "받은 %s 버프에 보답할 때:"
L["Meeting somebody a third time:"] = "같은 사람을 세 번째 만났을 때:"
